const lessons = [
  {"num": 4, "time": "00:01:30,000 --> 00:01:53,519", "arabic": "أَيُّهَا الْمُسْلِمُونَ، إِنَّ هَذَا الْكَافِرَ نَقْفُورَ نَقَضَ الْعَهْدَ مَرَّتَيْنِ", "segs": [{"ar": "أَيُّهَا الْمُسْلِمُونَ", "uz": "Ey musulmonlar"}, {"ar": "إِنَّ هَذَا الْكَافِرَ نَقْفُورَ نَقَضَ الْعَهْدَ مَرَّتَيْنِ", "uz": "bu kofir Naqfur ahdni ikki marta buzdi"}], "full_uz": "Ey musulmonlar, bu kofir Naqfur ahdni ikki marta buzdi.", "note": null},
  {"num": 7, "time": "00:01:53,519 --> 00:02:00,320", "arabic": "تَمَسَّكُوا بِالْإِيمَانِ وَلَا تَهَابُوا", "segs": null, "full_uz": "Imonga mahkam yopishing va qo'rqmang.", "note": null},
  {"num": 9, "time": "00:02:00,320 --> 00:02:02,299", "arabic": "اَللَّهُ أَكْبَرُ", "segs": null, "full_uz": "Alloh buyukdir.", "note": null},
  {"num": 10, "time": "00:02:02,299 --> 00:02:16,180", "arabic": "فَإِمَّا طَرِيقٌ إِلَى النَّصْرِ وَإِمَّا طَرِيقٌ إِلَى الْجَنَّةِ", "segs": [{"ar": "فَإِمَّا طَرِيقٌ إِلَى النَّصْرِ", "uz": "Yo g'alabaga yo'l"}, {"ar": "وَإِمَّا طَرِيقٌ إِلَى الْجَنَّةِ", "uz": "yo jannatga yo'l"}], "full_uz": "Yo g'alabaga yo'l, yo jannatga yo'l.", "note": null},
  {"num": 12, "time": "00:02:27,699 --> 00:02:36,659", "arabic": "اَللَّهُ أَكْبَرُ", "segs": null, "full_uz": "Alloh buyukdir.", "note": null},
  {"num": 21, "time": "00:06:27,699 --> 00:06:51,639", "arabic": "بَعْدَ أَنْ غَادَرْتِنِي تَذَكَّرْتُ أَمْرًا مُهِمًّا فَقُلْتُ لَا بُدَّ أَنْ أَقُولَهُ لَكِ", "segs": [{"ar": "بَعْدَ أَنْ غَادَرْتِنِي تَذَكَّرْتُ أَمْرًا مُهِمًّا", "uz": "Sendan ajralganimdan keyin muhim bir narsani esladim"}, {"ar": "فَقُلْتُ لَا بُدَّ أَنْ أَقُولَهُ لَكِ", "uz": "shuning uchun senga aytishim shart deb o'yladim"}], "full_uz": "Sendan ajralganimdan keyin muhim bir narsani esladim, shuning uchun senga aytishim shart deb o'yladim.", "note": null},
  {"num": 22, "time": "00:06:51,639 --> 00:06:56,899", "arabic": "اَلْحَمْدُ لِلَّهِ لَقَدْ تَوَقَّعْتُ عَوْدَتَكَ، تَفَضَّلْ تَفَضَّلْ قُلْ إِنِّي أَسْمَعُكَ", "segs": [{"ar": "اَلْحَمْدُ لِلَّهِ لَقَدْ تَوَقَّعْتُ عَوْدَتَكَ", "uz": "Alhamdulillah, qaytishingni kutgan edim"}, {"ar": "تَفَضَّلْ تَفَضَّلْ قُلْ إِنِّي أَسْمَعُكَ", "uz": "marhamat, marhamat, ayt, eshityapman"}], "full_uz": "Alhamdulillah, qaytishingni kutgan edim — marhamat, marhamat, ayt, eshityapman.", "note": null},
  {"num": 24, "time": "00:06:56,899 --> 00:07:08,199", "arabic": "جَارِيَتُنَا رَغَدُ، الْفَتَاةُ الَّتِي تَحَدَّثْنَا عَنْهَا آنِفًا، لَقَدْ كَانَتْ تَنْتَابُهَا نَوْبَاتٌ مِنَ الْجُنُونِ فَتَظُنُّ نَفْسَهَا فَتَاةً حُرَّةً وَتُدْعَى فَوْزَ", "segs": [{"ar": "جَارِيَتُنَا رَغَدُ، الْفَتَاةُ الَّتِي تَحَدَّثْنَا عَنْهَا آنِفًا", "uz": "Bizning cho'rimiz Rag'ad, hozirgina gaplashgan qizimiz"}, {"ar": "لَقَدْ كَانَتْ تَنْتَابُهَا نَوْبَاتٌ مِنَ الْجُنُونِ", "uz": "uni ba'zan telbalik xurujlari tutardi"}, {"ar": "فَتَظُنُّ نَفْسَهَا فَتَاةً حُرَّةً وَتُدْعَى فَوْزَ", "uz": "o'zini ozod qiz deb o'ylab, Favz deb atalardi"}], "full_uz": "Bizning cho'rimiz Rag'ad — hozirgina gaplashgan qizimiz — uni ba'zan telbalik xurujlari tutar, o'zini ozod qiz deb o'ylab, Favz deb ataladi.", "note": null},
  {"num": 27, "time": "00:07:08,199 --> 00:07:15,599", "arabic": "لَكِنَّهَا سَرِيعًا مَا كَانَتْ تَعُودُ إِلَى رُشْدِهَا وَتَتَذَكَّرُ اسْمَهَا الْحَقِيقِيَّ", "segs": [{"ar": "لَكِنَّهَا سَرِيعًا مَا كَانَتْ تَعُودُ إِلَى رُشْدِهَا", "uz": "Ammo tez orada o'ziga kelardi"}, {"ar": "وَتَتَذَكَّرُ اسْمَهَا الْحَقِيقِيَّ", "uz": "va haqiqiy ismini eslardi"}], "full_uz": "Ammo tez orada o'ziga kelib, haqiqiy ismini eslardi.", "note": null},
  {"num": 28, "time": "00:07:15,599 --> 00:07:19,819", "arabic": "أَلَا تَعْرِفُ مِنْ أَيِّ مَدِينَةٍ هِيَ؟", "segs": null, "full_uz": "Qaysi shahardan ekanini bilmaysanmi?", "note": null},
  {"num": 29, "time": "00:07:19,819 --> 00:07:25,819", "arabic": "لَا لَا لَا أَعْرِفُ، لَقَدْ كَانَتْ قَلِيلَةَ الْكَلَامِ كَثِيرَةَ الْوُجُومِ، لَكِنَّهَا كَانَتْ مُتَمَرِّدَةً", "segs": [{"ar": "لَا لَا لَا أَعْرِفُ", "uz": "Yo'q, yo'q, bilmayman"}, {"ar": "لَقَدْ كَانَتْ قَلِيلَةَ الْكَلَامِ كَثِيرَةَ الْوُجُومِ", "uz": "u kam gapiradigan, ko'p g'amgin edi"}, {"ar": "لَكِنَّهَا كَانَتْ مُتَمَرِّدَةً", "uz": "lekin isyonkor edi"}], "full_uz": "Yo'q, yo'q, bilmayman — u kam gapiradigan, ko'p g'amgin edi, lekin isyonkor edi.", "note": "اَلْوُجُوم — g'amga botib, kam gapirib qolish holati."},
  {"num": 31, "time": "00:07:25,819 --> 00:07:29,240", "arabic": "لِذَلِكَ فَكَّرْنَا أَنَا وَزَوْجِي بِبَيْعِهَا وَالتَّخَلُّصِ مِنْهَا", "segs": null, "full_uz": "Shu sababli men va erim uni sotib, undan qutulishni o'yladik.", "note": null},
  {"num": 32, "time": "00:07:29,240 --> 00:07:33,159", "arabic": "وَلِمَنْ بِعْتُمُوهَا؟ لِرَجُلٍ يُدْعَى شَفِيعٌ", "segs": [{"ar": "وَلِمَنْ بِعْتُمُوهَا؟", "uz": "Kimga sotdingiz?"}, {"ar": "لِرَجُلٍ يُدْعَى شَفِيعٌ", "uz": "Shafi' degan bir kishiga"}], "full_uz": "Kimga sotdingiz? Shafi' degan bir kishiga.", "note": null},
  {"num": 34, "time": "00:07:33,159 --> 00:07:36,599", "arabic": "هُوَ حَارِسٌ مِنْ حُرَّاسِ أَمِيرِ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدِ", "segs": null, "full_uz": "U Amir al-Mo'minin Horun ar-Rashidning soqchilaridan biri.", "note": null},
  {"num": 36, "time": "00:07:38,120 --> 00:07:44,480", "arabic": "أَلَا تَعْرِفُ أَيْنَ يَسْكُنُ شَفِيعٌ هَذَا؟ مَا أَعْرِفُهُ قُلْتُهُ لَكَ لِأَنِّي رَأَيْتُكَ مُهْتَمًّا لِأَمْرِهَا", "segs": [{"ar": "أَلَا تَعْرِفُ أَيْنَ يَسْكُنُ شَفِيعٌ هَذَا؟", "uz": "Bu Shafi' qayerda yashashini bilmaysanmi?"}, {"ar": "مَا أَعْرِفُهُ قُلْتُهُ لَكَ لِأَنِّي رَأَيْتُكَ مُهْتَمًّا لِأَمْرِهَا", "uz": "Bilganimni senga aytdim, chunki u haqida qiziqib qolganingni ko'rdim"}], "full_uz": "Bu Shafi' qayerda yashashini bilmaysanmi? Bilganimni senga aytdim, chunki u haqida qiziqib qolganingni ko'rdim.", "note": null},
  {"num": 38, "time": "00:07:44,480 --> 00:07:49,139", "arabic": "رَغْمَ أَنِّي مُتَأَكِّدٌ أَنَّهَا فَتَاةٌ أُخْرَى، جَزَاكَ اللَّهُ خَيْرًا", "segs": [{"ar": "رَغْمَ أَنِّي مُتَأَكِّدٌ أَنَّهَا فَتَاةٌ أُخْرَى", "uz": "Garchi u boshqa qiz ekaniga ishonchim komil bo'lsa-da"}, {"ar": "جَزَاكَ اللَّهُ خَيْرًا", "uz": "Alloh senga yaxshilik bersin"}], "full_uz": "Garchi u boshqa qiz ekaniga ishonchim komil bo'lsa-da. Alloh senga yaxshilik bersin.", "note": null},
  {"num": 40, "time": "00:07:49,139 --> 00:07:51,379", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom.", "note": null},
  {"num": 42, "time": "00:07:51,379 --> 00:08:01,519", "arabic": "فَوْزُ، لَا بُدَّ أَنْ أَجِدَهَا، لَا بُدَّ أَنْ أَجِدَهَا", "segs": null, "full_uz": "Favz... Uni albatta topishim kerak, albatta topishim kerak.", "note": null},
  {"num": 45, "time": "00:08:16,980 --> 00:08:18,420", "arabic": "قَلِقَةٌ عَلَى أَبِي", "segs": null, "full_uz": "Otam haqida xavotirdaman.", "note": null},
  {"num": 46, "time": "00:08:18,420 --> 00:08:23,620", "arabic": "وَهَلْ أَبُوكَ مِمَّنْ يُقْلَقُ عَلَيْهِ؟", "segs": null, "full_uz": "Otang xavotir olinadigan odamlardanmi?", "note": null},
  {"num": 47, "time": "00:08:23,620 --> 00:08:26,520", "arabic": "هُوَ يَعْرِفُ كَيْفَ يُدِيرُ حُرُوبَهُ وَكَيْفَ يَنْتَصِرُ", "segs": [{"ar": "هُوَ يَعْرِفُ كَيْفَ يُدِيرُ حُرُوبَهُ", "uz": "U janglarini qanday boshqarishni biladi"}, {"ar": "وَكَيْفَ يَنْتَصِرُ", "uz": "va qanday g'alaba qozonishni"}], "full_uz": "U janglarini qanday boshqarishni va qanday g'alaba qozonishni biladi.", "note": null},
  {"num": 48, "time": "00:08:26,520 --> 00:08:29,400", "arabic": "تَعَالَ يَا أُمِّي، اِجْلِسْ", "segs": null, "full_uz": "Kel, o'g'lim, o'tir.", "note": null},
  {"num": 50, "time": "00:08:29,400 --> 00:08:34,180", "arabic": "اِحْرِصْ عَلَى أَنْ تَكُونَ مِثْلَ أَبِيكَ أَيُّهَا الِابْنُ", "segs": null, "full_uz": "Otangga o'xshashga harakat qil, o'g'lim.", "note": null},
  {"num": 51, "time": "00:08:34,180 --> 00:08:37,600", "arabic": "سَأَكُونُ مِثْلَ أَبِي وَكَمَا تَرْغَبِينَ يَا أُمِّي", "segs": null, "full_uz": "Otamga o'xshab, siz istagandek bo'laman, onajon.", "note": null},
  {"num": 52, "time": "00:08:37,600 --> 00:08:39,600", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا وَلَدِي", "segs": null, "full_uz": "Alloh senga barakot bersin, o'g'lim.", "note": null},
  {"num": 53, "time": "00:08:48,419 --> 00:09:03,159", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom va rahmatullohi va barakatuh.", "note": null},
  {"num": 55, "time": "00:09:03,159 --> 00:09:06,159", "arabic": "أَهْلًا بِابْنِ حَنْبَلٍ، اُعْذُرْنِي عَلَى تَأَخُّرِي يَا شَيْخِي", "segs": [{"ar": "أَهْلًا بِابْنِ حَنْبَلٍ", "uz": "Ibn Hanbalga xush kelibsiz"}, {"ar": "اُعْذُرْنِي عَلَى تَأَخُّرِي يَا شَيْخِي", "uz": "Kechikkanim uchun meni afv eting, shayxim"}], "full_uz": "Ibn Hanbalga xush kelibsiz. Kechikkanim uchun meni afv eting, shayxim.", "note": null},
  {"num": 57, "time": "00:09:06,159 --> 00:09:10,759", "arabic": "لَا بَأْسَ عَلَيْكَ، لَا بَأْسَ عَلَيْكَ، لَا أَرَى ابْنَ نُوحٍ وَابْنَ مَعِينٍ مَعَكَ", "segs": [{"ar": "لَا بَأْسَ عَلَيْكَ، لَا بَأْسَ عَلَيْكَ", "uz": "Hech qisi yo'q, hech qisi yo'q"}, {"ar": "لَا أَرَى ابْنَ نُوحٍ وَابْنَ مَعِينٍ مَعَكَ", "uz": "Ibn Nuh va Ibn Ma'inni sen bilan ko'rmayapman"}], "full_uz": "Hech qisi yo'q, hech qisi yo'q — Ibn Nuh va Ibn Ma'inni sen bilan ko'rmayapman.", "note": null},
  {"num": 59, "time": "00:09:10,759 --> 00:09:16,659", "arabic": "عَسَى أَنْ يَكُونَ بِخَيْرٍ، هُمَا بِخَيْرٍ وَالْحَمْدُ لِلَّهِ، وَلَكِنْ ثَمَّ مَا يَشْغَلُهُمَا وَسَيَلْحَقَانِ بِي", "segs": [{"ar": "عَسَى أَنْ يَكُونَ بِخَيْرٍ", "uz": "Umid qilamanki, tuzuk bo'lishsin"}, {"ar": "هُمَا بِخَيْرٍ وَالْحَمْدُ لِلَّهِ", "uz": "Ikkalasi ham yaxshi, alhamdulillah"}, {"ar": "وَلَكِنْ ثَمَّ مَا يَشْغَلُهُمَا وَسَيَلْحَقَانِ بِي", "uz": "lekin ularni band qilgan narsa bor, meni quvib yetadi"}], "full_uz": "Umid qilamanki, tuzuk bo'lishsin. Ikkalasi ham yaxshi, alhamdulillah, lekin ularni band qilgan narsa bor, meni quvib yetadi.", "note": null},
  {"num": 62, "time": "00:09:16,659 --> 00:09:19,519", "arabic": "إِنْ شَاءَ اللَّهُ خَيْرٌ، تَفَضَّلْ تَفَضَّلْ", "segs": null, "full_uz": "Alloh xohlasa, xayrli bo'lsin. Marhamat, marhamat.", "note": null},
  {"num": 64, "time": "00:09:19,519 --> 00:09:24,319", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، عَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum. Alaykum assalom va rahmatulloh.", "note": null},
  {"num": 66, "time": "00:09:24,319 --> 00:09:39,639", "arabic": "شَرَعَ اللَّهُ لَنَا الْجِهَادَ فِي سَبِيلِهِ لِلْغَايَاتِ الشَّرْعِيَّةِ الْمَعْرُوفَةِ، لَكِنْ وَفْقَ مَا أَمَرَ وَشَرَعَ", "segs": [{"ar": "شَرَعَ اللَّهُ لَنَا الْجِهَادَ فِي سَبِيلِهِ لِلْغَايَاتِ الشَّرْعِيَّةِ الْمَعْرُوفَةِ", "uz": "Alloh bizga o'z yo'lida jihodni ma'lum shar'iy maqsadlar uchun farz qildi"}, {"ar": "لَكِنْ وَفْقَ مَا أَمَرَ وَشَرَعَ", "uz": "lekin U buyurgan va qonunlashtirgan tarzda"}], "full_uz": "Alloh bizga o'z yo'lida jihodni ma'lum shar'iy maqsadlar uchun farz qildi — lekin U buyurgan va qonunlashtirgan tarzda.", "note": null},
  {"num": 69, "time": "00:09:39,639 --> 00:09:47,879", "arabic": "قَالَ تَعَالَى: وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ وَلَا تَعْتَدُوا", "segs": [{"ar": "قَالَ تَعَالَى", "uz": "Alloh taolo aytdi"}, {"ar": "وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ وَلَا تَعْتَدُوا", "uz": "Sizlar bilan urushayotganlar bilan Alloh yo'lida urushing va (haddan) oshmang"}], "full_uz": "Alloh taolo aytdi: «Sizlar bilan urushayotganlar bilan Alloh yo'lida urushing va (haddan) oshmang».", "note": "Bu Qur'oni karim, Baqara surasi 190-oyatidan iqtibos."},
  {"num": 72, "time": "00:09:47,879 --> 00:09:50,700", "arabic": "إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ", "segs": null, "full_uz": "Albatta, Alloh haddan oshuvchilarni sevmaydi.", "note": "Baqara surasi 190-oyatining davomi."},
  {"num": 73, "time": "00:09:50,700 --> 00:09:59,059", "arabic": "فَأَذِنَ اللَّهُ لَنَا بِقِتَالِ مَنْ قَاتَلَنَا، وَنَهَانَا عَنِ الِاعْتِدَاءِ كَالْمُثْلَةِ وَالْغُلُولِ", "segs": [{"ar": "فَأَذِنَ اللَّهُ لَنَا بِقِتَالِ مَنْ قَاتَلَنَا", "uz": "Alloh bizga urushganlar bilan urushishga ruxsat berdi"}, {"ar": "وَنَهَانَا عَنِ الِاعْتِدَاءِ كَالْمُثْلَةِ وَالْغُلُولِ", "uz": "ammo tan qiynash va o'ljadan berkitish kabi tajovuzlardan qaytardi"}], "full_uz": "Alloh bizga urushganlar bilan urushishga ruxsat berdi, ammo tan qiynash (musla) va o'ljadan berkitish (g'ulul) kabi tajovuzlardan qaytardi.", "note": "اَلْمُثْلَة — jasadni buzish; اَلْغُلُول — o'ljadan yashirincha o'zlashtirish."},
  {"num": 75, "time": "00:09:59,059 --> 00:10:07,299", "arabic": "وَقَتْلُ مَنْ لَا يَحِلُّ قَتْلُهُ مِنَ النِّسَاءِ وَالصِّبْيَانِ وَالشُّيُوخِ وَمَنْ فِي حُكْمِهِمْ", "segs": [{"ar": "وَقَتْلُ مَنْ لَا يَحِلُّ قَتْلُهُ مِنَ النِّسَاءِ وَالصِّبْيَانِ وَالشُّيُوخِ", "uz": "Va o'ldirilishi joiz bo'lmagan ayollar, bolalar, keksalarni o'ldirishdan"}, {"ar": "وَمَنْ فِي حُكْمِهِمْ", "uz": "hamda ularning hukmidagilarni ham"}], "full_uz": "Va o'ldirilishi joiz bo'lmagan ayollar, bolalar, keksalar hamda ularning hukmidagilarni o'ldirishdan (qaytardi).", "note": null},
  {"num": 77, "time": "00:10:07,299 --> 00:10:17,860", "arabic": "إِنَّ اللَّهَ لَا يُحِبُّ الَّذِينَ يُجَاوِزُونَ حُدُودَهُ فَيَسْتَحِلُّونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ", "segs": [{"ar": "إِنَّ اللَّهَ لَا يُحِبُّ الَّذِينَ يُجَاوِزُونَ حُدُودَهُ", "uz": "Albatta, Alloh o'z chegaralaridan tajovuz qiluvchilarni sevmaydi"}, {"ar": "فَيَسْتَحِلُّونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ", "uz": "va Alloh va Rasuli harom qilgan narsani halol sanaydilar"}], "full_uz": "Albatta, Alloh o'z chegaralaridan tajovuz qilib, Alloh va Rasuli harom qilgan narsani halol sanovchilarni sevmaydi.", "note": null},
  {"num": 79, "time": "00:10:17,860 --> 00:10:22,860", "arabic": "اَللَّهُ أَكْبَرُ", "segs": null, "full_uz": "Alloh buyukdir.", "note": null},
  {"num": 92, "time": "00:15:12,240 --> 00:15:14,240", "arabic": "مَرْحَبًا", "segs": null, "full_uz": "Xush kelibsiz.", "note": null},
  {"num": 94, "time": "00:16:11,240 --> 00:16:20,240", "arabic": "اَللَّهُ أَكْبَرُ", "segs": null, "full_uz": "Alloh buyukdir.", "note": null},
  {"num": 95, "time": "00:16:33,240 --> 00:16:40,240", "arabic": "لَا أَدْرِي لِمَ يُحَدِّثُنِي قَلْبِي أَنَّ هَذِهِ الْجَارِيَةَ هِيَ أُخْتُ شَهْنَازَ، هَلْ أُخْبِرُ شَهْنَازَ بِمَا عَرَفْتُ؟", "segs": [{"ar": "لَا أَدْرِي لِمَ يُحَدِّثُنِي قَلْبِي أَنَّ هَذِهِ الْجَارِيَةَ هِيَ أُخْتُ شَهْنَازَ", "uz": "Bilmayman, nega yuragim bu cho'ri Shahnozning singlisi ekaniga sezgi berayapti"}, {"ar": "هَلْ أُخْبِرُ شَهْنَازَ بِمَا عَرَفْتُ؟", "uz": "Shahnozga bilganimni aytaymi?"}], "full_uz": "Bilmayman, nega yuragim bu cho'ri Shahnozning singlisi ekaniga sezgi berayapti — Shahnozga bilganimni aytaymi?", "note": null},
  {"num": 97, "time": "00:16:41,240 --> 00:16:48,539", "arabic": "لَا لَا لَا يَجِبُ أَنْ تَعْرِفَ شَيْئًا، لَنْ أَجْعَلَهَا تَتَعَلَّقُ بِأَمَلٍ سَبَبُهُ لَيْسَ بِيَدِي", "segs": [{"ar": "لَا لَا لَا يَجِبُ أَنْ تَعْرِفَ شَيْئًا", "uz": "Yo'q, yo'q, hech narsani bilmasligi kerak"}, {"ar": "لَنْ أَجْعَلَهَا تَتَعَلَّقُ بِأَمَلٍ سَبَبُهُ لَيْسَ بِيَدِي", "uz": "uni o'z qo'limda bo'lmagan sabab bilan bog'liq umidga osilib qolishiga yo'l qo'ymayman"}], "full_uz": "Yo'q, yo'q, hech narsani bilmasligi kerak — uni o'z qo'limda bo'lmagan sabab bilan bog'liq umidga osilib qolishiga yo'l qo'ymayman.", "note": null},
  {"num": 99, "time": "00:16:48,539 --> 00:16:53,379", "arabic": "أَوَّلُ مَا يَجِبُ أَنْ أَفْعَلَهُ هُوَ الْبَحْثُ عَنْ شَفِيعٍ هَذَا", "segs": [{"ar": "أَوَّلُ مَا يَجِبُ أَنْ أَفْعَلَهُ", "uz": "Birinchi qilishim kerak bo'lgan narsa"}, {"ar": "هُوَ الْبَحْثُ عَنْ شَفِيعٍ هَذَا", "uz": "bu Shafi'ni izlashdir"}], "full_uz": "Birinchi qilishim kerak bo'lgan narsa — bu Shafi'ni izlashdir.", "note": null},
  {"num": 100, "time": "00:17:11,240 --> 00:17:17,559", "arabic": "رَافَقَتْكُمُ السَّلَامَةُ، أَرْجُو أَنْ تَنْقُلُوا سَلَامِي وَأَشْوَاقِي لِبَغْدَادَ وَأَهْلِهَا", "segs": [{"ar": "رَافَقَتْكُمُ السَّلَامَةُ", "uz": "Omonlik sizga hamroh bo'lsin"}, {"ar": "أَرْجُو أَنْ تَنْقُلُوا سَلَامِي وَأَشْوَاقِي لِبَغْدَادَ وَأَهْلِهَا", "uz": "salomim va sog'inchimni Bag'dodga va uning ahliga yetkazishingizni umid qilaman"}], "full_uz": "Omonlik sizga hamroh bo'lsin — salomim va sog'inchimni Bag'dodga va uning ahliga yetkazishingizni umid qilaman.", "note": null},
  {"num": 102, "time": "00:17:17,559 --> 00:17:25,420", "arabic": "وَنَحْنُ نَنْتَظِرُ قُدُومَكَ إِلَى بَغْدَادَ بِفَارِغِ الصَّبْرِ يَا شَيْخُ، إِنْ شَاءَ اللَّهُ شَرَفٌ كَبِيرٌ لِي يَا ابْنَ حَنْبَلٍ", "segs": [{"ar": "وَنَحْنُ نَنْتَظِرُ قُدُومَكَ إِلَى بَغْدَادَ بِفَارِغِ الصَّبْرِ يَا شَيْخُ", "uz": "Biz sizning Bag'dodga kelishingizni sabrsizlik bilan kutamiz, shayx"}, {"ar": "إِنْ شَاءَ اللَّهُ شَرَفٌ كَبِيرٌ لِي يَا ابْنَ حَنْبَلٍ", "uz": "Alloh xohlasa, bu men uchun katta sharaf, Ibn Hanbal"}], "full_uz": "Biz sizning Bag'dodga kelishingizni sabrsizlik bilan kutamiz, shayx. Alloh xohlasa, bu men uchun katta sharaf, Ibn Hanbal.", "note": null},
  {"num": 104, "time": "00:17:25,420 --> 00:17:32,620", "arabic": "نَسْتَوْدِعُكَ اللَّهَ، بِأَمَانِ اللَّهِ، اَلسَّلَامُ عَلَيْكُمْ، مَعَ السَّلَامِ", "segs": null, "full_uz": "Seni Allohga topshiraman. Alloh amonatida bo'l. Assalomu alaykum. Xayr, salomat bo'ling.", "note": null},
  {"num": 113, "time": "00:18:11,240 --> 00:18:21,779", "arabic": "هَلْ مِنْ أَخْبَارٍ جَدِيدَةٍ يَا أَبَا سَرْحَانَ؟", "segs": null, "full_uz": "Yangi xabarlar bormi, Abu Sarhon?", "note": null},
  {"num": 114, "time": "00:18:21,779 --> 00:18:27,319", "arabic": "اَلْأَخْبَارُ الَّتِي تَأْتِي مِنْ طُوسَ غَيْرُ مُطْمَئِنَّةٍ يَا أَبَا دُلَامَةَ، عَنْ أَمِيرِ الْمُؤْمِنِينَ؟ أَجَلْ", "segs": [{"ar": "اَلْأَخْبَارُ الَّتِي تَأْتِي مِنْ طُوسَ غَيْرُ مُطْمَئِنَّةٍ يَا أَبَا دُلَامَةَ", "uz": "Tus shahridan kelayotgan xabarlar tinchlantiruvchi emas, Abu Dulama"}, {"ar": "عَنْ أَمِيرِ الْمُؤْمِنِينَ؟ أَجَلْ", "uz": "Amir al-Mo'minin haqidami? Ha"}], "full_uz": "Tus shahridan kelayotgan xabarlar tinchlantiruvchi emas, Abu Dulama. Amir al-Mo'minin haqidami? Ha.", "note": null},
  {"num": 117, "time": "00:18:27,740 --> 00:18:35,799", "arabic": "يَبْدُو أَنَّ مَوْلَانَا أَمِيرَ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدَ يُعَانِي مِنْ مَرَضٍ عُضَالٍ أَعْجَزَهُ عَنِ الرُّجُوعِ إِلَى بَغْدَادَ", "segs": [{"ar": "يَبْدُو أَنَّ مَوْلَانَا أَمِيرَ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدَ يُعَانِي مِنْ مَرَضٍ عُضَالٍ", "uz": "Xo'jayinimiz Amir al-Mo'minin Horun ar-Rashid og'ir kasallikka chalinganga o'xshaydi"}, {"ar": "أَعْجَزَهُ عَنِ الرُّجُوعِ إِلَى بَغْدَادَ", "uz": "bu uni Bag'dodga qaytishdan ojiz qilib qo'ygan"}], "full_uz": "Xo'jayinimiz Amir al-Mo'minin Horun ar-Rashid og'ir kasallikka chalinib, Bag'dodga qaytishga imkoni yo'qday tuyuladi.", "note": null},
  {"num": 119, "time": "00:18:35,799 --> 00:18:42,300", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، أَتَظُنُّ أَنَّهُ؟ اَلْأَعْمَارُ بِيَدِ اللَّهِ", "segs": [{"ar": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "uz": "La havla va la quvvata illa billah"}, {"ar": "أَتَظُنُّ أَنَّهُ؟", "uz": "Sen o'ylaysanmi u...?"}, {"ar": "اَلْأَعْمَارُ بِيَدِ اللَّهِ", "uz": "Umrlar Allohning qo'lidadir"}], "full_uz": "La havla va la quvvata illa billah. Sen o'ylaysanmi u...? Umrlar Allohning qo'lidadir.", "note": null},
  {"num": 122, "time": "00:18:42,300 --> 00:18:50,640", "arabic": "يَا أَبَا هُلُولٍ، مَاذَا تُرِيدُ؟", "segs": [{"ar": "يَا أَبَا هُلُولٍ", "uz": "Ey Abu Hulul"}, {"ar": "مَاذَا تُرِيدُ؟", "uz": "nima istaysan?"}], "full_uz": "Ey Abu Hulul, nima istaysan?", "note": null},
  {"num": 124, "time": "00:18:50,640 --> 00:18:54,720", "arabic": "أَلَا تَرَانِي عَلَى عَجَلَةٍ مِنْ أَمْرِي؟ وَمَاذَا وَرَاءَكَ؟", "segs": [{"ar": "أَلَا تَرَانِي عَلَى عَجَلَةٍ مِنْ أَمْرِي؟", "uz": "Shoshilib turganimni ko'rmayapsanmi?"}, {"ar": "وَمَاذَا وَرَاءَكَ؟", "uz": "Nima maqsadda kelding?"}], "full_uz": "Shoshilib turganimni ko'rmayapsanmi? Nima maqsadda kelding?", "note": null},
  {"num": 126, "time": "00:18:56,320 --> 00:19:00,720", "arabic": "ذَاهِبٌ إِلَى الْمَقْبَرَةِ سَأُخْبِرُ الْمَوْتَى", "segs": null, "full_uz": "Qabristonga borayapman — o'liklarga xabar beraman.", "note": null},
  {"num": 128, "time": "00:19:00,720 --> 00:19:06,160", "arabic": "أَنَّ ضَيْفًا كَرِيمًا سَيَزُورُهُمْ عَمَّا قَرِيبٍ وَيَحُلُّ", "segs": null, "full_uz": "Tez orada ularga izzatli mehmon tashrif buyurib, joylashadi deb.", "note": null},
  {"num": 131, "time": "00:19:06,160 --> 00:19:09,900", "arabic": "مَاذَا تَقْصِدُ؟ كُلٌّ إِلَيْنَا رَاجِعُونَ", "segs": null, "full_uz": "Nimani nazarda tutyapsan? Barchamiz Bizga qaytuvchimiz.", "note": "\"كُلٌّ إِلَيْنَا رَاجِعُونَ\" — Qur'ondagi \"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ\" ma'nosiga yaqin ibora."},
  {"num": 135, "time": "00:19:15,820 --> 00:19:33,480", "arabic": "قُلْ إِنَّ الْمَوْتَ الَّذِي تَفِرُّونَ مِنْهُ فَإِنَّهُ مُلَاقِيكُمْ", "segs": null, "full_uz": "Ayt: albatta, siz undan qochayotgan o'lim sizga albatta yetib boradi.", "note": "Bu Qur'oni karim, Jumu'a surasi 8-oyatidan iqtibos."},
  {"num": 143, "time": "00:20:09,900 --> 00:20:32,620", "arabic": "إِلَى هَذِهِ الْحُفَيْرَةِ تَعُودُ يَا ابْنَ آدَمَ، إِلَى التُّرَابِ تَعُودُ", "segs": [{"ar": "إِلَى هَذِهِ الْحُفَيْرَةِ تَعُودُ يَا ابْنَ آدَمَ", "uz": "Ey Odam farzandi, sen shu chuqurchaga qaytasan"}, {"ar": "إِلَى التُّرَابِ تَعُودُ", "uz": "tuproqqa qaytasan"}], "full_uz": "Ey Odam farzandi, sen shu chuqurchaga qaytasan — tuproqqa qaytasan.", "note": null},
  {"num": 145, "time": "00:20:39,700 --> 00:20:49,200", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", "segs": null, "full_uz": "Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": "Baqara surasi, 2:156-oyatdan."},
  {"num": 146, "time": "00:20:49,200 --> 00:21:02,700", "arabic": "يَا مَنْ لَا يَزُولُ مُلْكُهُ، ارْحَمْ مَنْ زَالَ مُلْكُهُ", "segs": [{"ar": "يَا مَنْ لَا يَزُولُ مُلْكُهُ", "uz": "Ey mulki hech qachon zavol topmaydigan Zot"}, {"ar": "ارْحَمْ مَنْ زَالَ مُلْكُهُ", "uz": "mulki zavol topgan kishiga rahm qil"}], "full_uz": "Ey mulki hech qachon zavol topmaydigan Zot, mulki zavol topgan kishiga rahm qil.", "note": null},
  {"num": 148, "time": "00:21:09,700 --> 00:21:23,039", "arabic": "اَللَّهُمَّ انْفَعْنَا بِالْإِحْسَانِ وَاغْفِرْ لَنَا الْإِسَاءَةَ", "segs": [{"ar": "اَللَّهُمَّ انْفَعْنَا بِالْإِحْسَانِ", "uz": "Allohim, bizga ehson bilan naf ber"}, {"ar": "وَاغْفِرْ لَنَا الْإِسَاءَةَ", "uz": "va yomonligimizni mag'firat qil"}], "full_uz": "Allohim, bizga ehson bilan naf ber va yomonligimizni mag'firat qil.", "note": null},
  {"num": 151, "time": "00:21:23,039 --> 00:21:38,840", "arabic": "يَا مَنْ لَا يَمُوتُ، ارْحَمْ مَنْ يَمُوتُ", "segs": null, "full_uz": "Ey o'lmaydigan Zot, o'ladigan kishiga rahm qil.", "note": null},
  {"num": 155, "time": "00:21:38,839 --> 00:21:47,099", "arabic": "فِي ذَاكَ نَفْسِي يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Jonim shunga fido bo'lsin, ey Amir al-Mo'minin.", "note": null},
  {"num": 156, "time": "00:21:47,099 --> 00:21:54,179", "arabic": "أَخَائِفٌ أَنْتَ عَلَى مَوْلَاكَ يَا أَبَا الْعَبَّاسِ؟", "segs": null, "full_uz": "Xo'jayining haqida qo'rqyapsanmi, Abu al-Abbos?", "note": null},
  {"num": 157, "time": "00:22:04,179 --> 00:22:14,399", "arabic": "وَإِنَّهَا مِنْ قَوْمٍ كِرَامٍ يَزِيدُهُمْ شَمَاسًا وَصَبْرًا شِدَّةُ الْحِدْثَانِ", "segs": null, "full_uz": "Bu — zodagon qavmdan, ularga musibatning shiddati g'ayrat va sabrni ko'proq beradi.", "note": "اَلْحِدْثَان — kutilmagan musibat, og'ir voqea."},
  {"num": 161, "time": "00:23:08,339 --> 00:23:34,139", "arabic": "مَا لِبَالِي يَا أُمَّ أَحْمَدَ الْيَوْمَ عَنَّا مَجْهُولٌ", "segs": null, "full_uz": "Bugun ko'nglimda nima kechayotgani, ey Ahmadning onasi, biz uchun noma'lum.", "note": null},
  {"num": 162, "time": "00:23:38,339 --> 00:23:47,839", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 164, "time": "00:23:50,980 --> 00:23:59,459", "arabic": "أَبَا الْمُغِيرَةِ، اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Abu al-Mug'ira. Assalomu alaykum va rahmatulloh.", "note": null},
  {"num": 166, "time": "00:23:59,459 --> 00:24:10,000", "arabic": "وَعَلَيْكَ سَلَامُ اللَّهِ يَا ابْنَ أَبِي دُؤَادٍ، إِنْ لَمْ يَخُنِّي ظَنِّي إِنَّهُ أَمْرٌ خَطِيرٌ يَشْغَلُ بَالَ الْأُمَّهَاتِ", "segs": [{"ar": "وَعَلَيْكَ سَلَامُ اللَّهِ يَا ابْنَ أَبِي دُؤَادٍ", "uz": "Va senga ham Allohning salomi, Ibn Abi Duvod"}, {"ar": "إِنْ لَمْ يَخُنِّي ظَنِّي إِنَّهُ أَمْرٌ خَطِيرٌ يَشْغَلُ بَالَ الْأُمَّهَاتِ", "uz": "Agar gumonim meni aldamasa, bu onalarning fikrini band qiladigan jiddiy bir masala"}], "full_uz": "Va senga ham Allohning salomi, Ibn Abi Duvod. Agar gumonim meni aldamasa, bu onalarning fikrini band qiladigan jiddiy bir masala.", "note": null},
  {"num": 169, "time": "00:24:10,000 --> 00:24:15,019", "arabic": "وَأَنَا فِي شَوْقٍ إِلَى سَمَاعِهِ، لَا تُنْقِصُكَ الْفِطْنَةُ يَا وَلَدِي", "segs": [{"ar": "وَأَنَا فِي شَوْقٍ إِلَى سَمَاعِهِ", "uz": "Uni eshitishga ishtiyoqmandman"}, {"ar": "لَا تُنْقِصُكَ الْفِطْنَةُ يَا وَلَدِي", "uz": "Farosating kam emas, o'g'lim"}], "full_uz": "Uni eshitishga ishtiyoqmandman. Farosating kam emas, o'g'lim.", "note": null},
  {"num": 171, "time": "00:24:15,019 --> 00:24:22,059", "arabic": "فَتَاةٌ عَلَى خُلُقٍ وَدِينٍ، غَايَةٌ فِي الْحُسْنِ وَالْجَمَالِ", "segs": null, "full_uz": "Axloqi va dinida a'lo, husn va jamolda benazir bir qiz.", "note": null},
  {"num": 173, "time": "00:24:22,059 --> 00:24:26,740", "arabic": "ثُمَّ مَاذَا يَا أُمَّهْ؟ فَكَّرْتُ أَنْ أَخْطُبَهَا لَكَ", "segs": [{"ar": "ثُمَّ مَاذَا يَا أُمَّهْ؟", "uz": "Xo'sh, keyin nima, onajon?"}, {"ar": "فَكَّرْتُ أَنْ أَخْطُبَهَا لَكَ", "uz": "Uni senga sovchilik qilishni o'yladim"}], "full_uz": "Xo'sh, keyin nima, onajon? Uni senga sovchilik qilishni o'yladim.", "note": null},
  {"num": 175, "time": "00:24:31,419 --> 00:24:40,379", "arabic": "لَنْ نَجِدَ أَطْيَبَ مِنْهَا دِينًا، وَلَا أَجْمَلَ خُلُقًا وَخَلْقًا، وَهِيَ مِنْ أَبْنَاءِ عُمُومَتِكَ الشَّيْبَانِيِّينَ", "segs": [{"ar": "لَنْ نَجِدَ أَطْيَبَ مِنْهَا دِينًا، وَلَا أَجْمَلَ خُلُقًا وَخَلْقًا", "uz": "Dinda undan yaxshirog'ini topolmaymiz, axloq va tashqi ko'rinishda ham undan chiroylirog'ini topolmaymiz"}, {"ar": "وَهِيَ مِنْ أَبْنَاءِ عُمُومَتِكَ الشَّيْبَانِيِّينَ", "uz": "u sening amakivachchalaring Shaybaniylardan"}], "full_uz": "Dinda undan yaxshirog'ini topolmaymiz, axloq va tashqi ko'rinishda undan chiroylirog'ini ham — u sening amakivachchalaring Shaybaniylardan.", "note": "خُلُق (ichki axloq) va خَلْق (tashqi qiyofa) so'zlari yozilishda o'xshash, ma'noda farqli — bu yerda ikkalasi ham maqtov uchun ishlatilgan."},
  {"num": 178, "time": "00:24:40,379 --> 00:24:51,279", "arabic": "نَعْرِفُهَا وَنَعْرِفُ أَهْلَهَا، مَتَى تَرَى أَنْ نُكَلِّمَ أَهْلَهَا؟", "segs": [{"ar": "نَعْرِفُهَا وَنَعْرِفُ أَهْلَهَا", "uz": "Uni ham, oilasini ham bilamiz"}, {"ar": "مَتَى تَرَى أَنْ نُكَلِّمَ أَهْلَهَا؟", "uz": "Qachon ularning oilasi bilan gaplashsak deb o'ylaysan?"}], "full_uz": "Uni ham, oilasini ham bilamiz. Qachon ularning oilasi bilan gaplashsak deb o'ylaysan?", "note": null},
  {"num": 180, "time": "00:24:57,579 --> 00:25:06,259", "arabic": "أَخْشَى أَنَّنِي سَأُؤَخِّرُكَ عَنْ مَشَاغِلِكَ قَلِيلًا يَا أَبَا الْمُغِيرَةِ، لَدَيَّ كَلَامٌ أُرِيدُ مِنْكَ أَنْ تَسْمَعَهُ جَيِّدًا", "segs": [{"ar": "أَخْشَى أَنَّنِي سَأُؤَخِّرُكَ عَنْ مَشَاغِلِكَ قَلِيلًا يَا أَبَا الْمُغِيرَةِ", "uz": "Qo'rqamanki, seni bir oz ishlaringdan to'xtatib qo'yaman, Abu al-Mug'ira"}, {"ar": "لَدَيَّ كَلَامٌ أُرِيدُ مِنْكَ أَنْ تَسْمَعَهُ جَيِّدًا", "uz": "senga diqqat bilan eshitishingni istagan gapim bor"}], "full_uz": "Qo'rqamanki, seni bir oz ishlaringdan to'xtatib qo'yaman, Abu al-Mug'ira — senga diqqat bilan eshitishingni istagan gapim bor.", "note": null},
  {"num": 182, "time": "00:25:06,259 --> 00:25:13,259", "arabic": "طَالَ الْجَفَاءُ بَيْنَنَا وَلَا أَرَى سَبَبًا مُقْنِعًا لَهُ، إِنَّ لَكَ مَنْزِلَةً عِنْدِي", "segs": [{"ar": "طَالَ الْجَفَاءُ بَيْنَنَا وَلَا أَرَى سَبَبًا مُقْنِعًا لَهُ", "uz": "Oramizdagi sovuqchilik uzoq davom etdi, unga ishonarli sabab ko'rmayapman"}, {"ar": "إِنَّ لَكَ مَنْزِلَةً عِنْدِي", "uz": "sening oldimda o'rning bor"}], "full_uz": "Oramizdagi sovuqchilik uzoq davom etdi, unga ishonarli sabab ko'rmayapman — sening oldimda o'rning bor.", "note": "اَلْجَفَاء — mehr-oqibatning sovushi, o'zaro yiroqlashish."},
  {"num": 185, "time": "00:25:13,259 --> 00:25:21,299", "arabic": "تَجْعَلُنِي حَرِيصًا أَنْ يَزُولَ هَذَا الْخِلَافُ وَتَعُودَ عَلَاقَتُنَا كَسَابِقٍ عَادِيَّةً", "segs": [{"ar": "تَجْعَلُنِي حَرِيصًا أَنْ يَزُولَ هَذَا الْخِلَافُ", "uz": "Bu meni ushbu ixtilofning bartaraf bo'lishiga qiziqtiradi"}, {"ar": "وَتَعُودَ عَلَاقَتُنَا كَسَابِقٍ عَادِيَّةً", "uz": "va munosabatimizning avvalgidek oddiy bo'lib qolishiga"}], "full_uz": "Bu meni ushbu ixtilofning bartaraf bo'lishiga va munosabatimizning avvalgidek oddiy bo'lib qolishiga qiziqtiradi.", "note": null},
  {"num": 187, "time": "00:25:21,299 --> 00:25:26,220", "arabic": "لَدَيَّ مَا يَشْغَلُنِي يَا ابْنَ أَبِي دُؤَادٍ، أَرْجُو أَنْ تُوجِزَ فِي كَلَامِكَ", "segs": [{"ar": "لَدَيَّ مَا يَشْغَلُنِي يَا ابْنَ أَبِي دُؤَادٍ", "uz": "Band qiladigan ishlarim bor, Ibn Abi Duvod"}, {"ar": "أَرْجُو أَنْ تُوجِزَ فِي كَلَامِكَ", "uz": "gapingda qisqa bo'lishingni so'rayman"}], "full_uz": "Band qiladigan ishlarim bor, Ibn Abi Duvod — gapingda qisqa bo'lishingni so'rayman.", "note": null},
  {"num": 189, "time": "00:25:26,220 --> 00:25:35,140", "arabic": "تَقُولُ مَا زَالَ الْوَقْتُ مُبَكِّرًا عَلَى هَذَا الْأَمْرِ؟ أَتَظُنُّ نَفْسَكَ يَافِعًا؟", "segs": [{"ar": "تَقُولُ مَا زَالَ الْوَقْتُ مُبَكِّرًا عَلَى هَذَا الْأَمْرِ؟", "uz": "Bu ish uchun hali erta, deysanmi?"}, {"ar": "أَتَظُنُّ نَفْسَكَ يَافِعًا؟", "uz": "O'zingni hali yosh deb o'ylaysanmi?"}], "full_uz": "Bu ish uchun hali erta, deysanmi? O'zingni hali yosh deb o'ylaysanmi?", "note": null},
  {"num": 191, "time": "00:25:35,140 --> 00:25:42,180", "arabic": "لَقَدْ تَجَاوَزْتَ الثَّلَاثِينَ مِنْ عُمُرِكَ يَا وَلَدِي، اُنْظُرْ إِلَى صَاحِبِكَ وَأَتْرَابِكَ", "segs": [{"ar": "لَقَدْ تَجَاوَزْتَ الثَّلَاثِينَ مِنْ عُمُرِكَ يَا وَلَدِي", "uz": "O'ttiz yoshdan o'tding, o'g'lim"}, {"ar": "اُنْظُرْ إِلَى صَاحِبِكَ وَأَتْرَابِكَ", "uz": "sherigingga va tengdoshlaringga qara"}], "full_uz": "O'ttiz yoshdan o'tding, o'g'lim — sherigingga va tengdoshlaringga qara.", "note": null},
  {"num": 193, "time": "00:25:42,180 --> 00:25:50,140", "arabic": "أَوْلَادُهُمْ أَصْبَحُوا صِبْيَانًا يَمْلَؤُونَ الْأَرْضَ، فَإِلَى مَتَى يَا وَلَدِي؟ إِلَى مَتَى؟", "segs": [{"ar": "أَوْلَادُهُمْ أَصْبَحُوا صِبْيَانًا يَمْلَؤُونَ الْأَرْضَ", "uz": "Ularning bolalari yer yuzini to'ldirgan bolakaylarga aylandi"}, {"ar": "فَإِلَى مَتَى يَا وَلَدِي؟ إِلَى مَتَى؟", "uz": "qachongacha, o'g'lim? Qachongacha?"}], "full_uz": "Ularning bolalari yer yuzini to'ldirgan bolakaylarga aylandi — qachongacha, o'g'lim? Qachongacha?", "note": null},
  {"num": 195, "time": "00:25:50,680 --> 00:25:55,280", "arabic": "إِلَى أَنْ يَشَاءَ رَبِّي شَيْئًا يَا أُمَّهْ، هَذَا جَوَابُ الْحَكِيمِ يَا وَلَدِي", "segs": [{"ar": "إِلَى أَنْ يَشَاءَ رَبِّي شَيْئًا يَا أُمَّهْ", "uz": "Robbim biror narsani xohlagunicha, onajon"}, {"ar": "هَذَا جَوَابُ الْحَكِيمِ يَا وَلَدِي", "uz": "Bu hakim kishining javobi, o'g'lim"}], "full_uz": "Robbim biror narsani xohlagunicha, onajon. Bu hakim kishining javobi, o'g'lim.", "note": null},
  {"num": 197, "time": "00:25:55,280 --> 00:26:01,140", "arabic": "قُلْ لِيَ الْأَسْبَابَ الَّتِي تَمْنَعُكَ مِنْ ذَلِكَ فَحَسْبُ", "segs": null, "full_uz": "Faqat seni undan to'sib turgan sabablarni ayt.", "note": null},
  {"num": 198, "time": "00:26:01,140 --> 00:26:10,700", "arabic": "اَلْأَسْبَابُ كَثِيرَةٌ يَا أُمَّهْ وَلَا حَاجَةَ أَنْ أُعِيدَ عَلَيْكِ مَا ذَكَرْتُ آنِفًا، مَا تَزْعُمُهُ مِنْ أَسْبَابٍ أَرَاهَا وَاهِيَةً لَا قِيمَةَ لَهَا عِنْدِي", "segs": [{"ar": "اَلْأَسْبَابُ كَثِيرَةٌ يَا أُمَّهْ", "uz": "Sabablar ko'p, onajon"}, {"ar": "وَلَا حَاجَةَ أَنْ أُعِيدَ عَلَيْكِ مَا ذَكَرْتُ آنِفًا", "uz": "avval aytganlarimni takrorlashning hojati yo'q"}, {"ar": "مَا تَزْعُمُهُ مِنْ أَسْبَابٍ", "uz": "Sen bahona qilgan sabablarni"}, {"ar": "أَرَاهَا وَاهِيَةً لَا قِيمَةَ لَهَا عِنْدِي", "uz": "bo'sh, mening nazdimda qadrsiz deb bilaman"}], "full_uz": "Sabablar ko'p, onajon, avval aytganlarimni takrorlashning hojati yo'q. Sen bahona qilgan sabablarni bo'sh, mening nazdimda qadrsiz deb bilaman.", "note": null},
  {"num": 200, "time": "00:26:10,700 --> 00:26:17,920", "arabic": "أَتَتَذَرَّعُ بِضِيقِ ذَاتِ الْيَدِ وَالِانْشِغَالِ بِالْعِلْمِ؟ إِنَّهَا سُنَّةُ الْحُكَمَاءِ وَالصَّالِحِينَ يَا وَلَدِي", "segs": [{"ar": "أَتَتَذَرَّعُ بِضِيقِ ذَاتِ الْيَدِ وَالِانْشِغَالِ بِالْعِلْمِ؟", "uz": "Qo'l qisqaligi va ilm bilan mashg'ullikni bahona qilyapsanmi?"}, {"ar": "إِنَّهَا سُنَّةُ الْحُكَمَاءِ وَالصَّالِحِينَ يَا وَلَدِي", "uz": "Bu hakim va solih kishilarning yo'lidir, o'g'lim"}], "full_uz": "Qo'l qisqaligi va ilm bilan mashg'ullikni bahona qilyapsanmi? Bu hakim va solih kishilarning yo'lidir, o'g'lim.", "note": "ضِيقُ ذَاتِ الْيَد — moddiy qiyinchilik, pul yetishmasligi."},
  {"num": 202, "time": "00:26:17,920 --> 00:26:26,480", "arabic": "ثُمَّ لَنْ أَخْطُبَ لَكَ بِنْتَ السُّلْطَانِ، بَلْ فَتَاةً لَا تَغِيبُ عَنْهَا مَعِيشَتُنَا وَلَا تَخْفَى عَنْهَا حَالُنَا", "segs": [{"ar": "ثُمَّ لَنْ أَخْطُبَ لَكَ بِنْتَ السُّلْطَانِ", "uz": "Yana men senga sulton qizini emas"}, {"ar": "بَلْ فَتَاةً لَا تَغِيبُ عَنْهَا مَعِيشَتُنَا وَلَا تَخْفَى عَنْهَا حَالُنَا", "uz": "balki turmush tarzimizdan bexabar bo'lmagan, ahvolimizdan yashirin qolmagan bir qizni sovchilik qilaman"}], "full_uz": "Yana men senga sulton qizini emas, balki turmush tarzimizdan bexabar bo'lmagan, ahvolimizdan yashirin qolmagan bir qizni sovchilik qilaman.", "note": null},
  {"num": 204, "time": "00:26:26,480 --> 00:26:35,039", "arabic": "أُمَّهْ، أَيُّ بَيْتٍ يَرْضَى أَنْ يُزَوِّجَ ابْنَتَهُ إِلَى رَجُلٍ فِي مِثْلِ حَالِي بِالْكَادِ يَجِدُ قُوتَ يَوْمِهِ", "segs": [{"ar": "أُمَّهْ، أَيُّ بَيْتٍ يَرْضَى", "uz": "Onajon, qaysi oila rozi bo'ladi"}, {"ar": "أَنْ يُزَوِّجَ ابْنَتَهُ إِلَى رَجُلٍ فِي مِثْلِ حَالِي", "uz": "mendek holdagi odamga qizini uzatishga"}, {"ar": "بِالْكَادِ يَجِدُ قُوتَ يَوْمِهِ", "uz": "kunlik rizqini zo'rg'a topadigan"}], "full_uz": "Onajon — qaysi oila kunlik rizqini zo'rg'a topadigan mendek holdagi odamga qizini uzatishga rozi bo'ladi?", "note": null},
  {"num": 207, "time": "00:26:35,039 --> 00:26:41,319", "arabic": "بَنَاتُ النَّاسِ أَمَانَةٌ يَا أُمَّهْ، لَا يُضَيِّعُهَا إِلَّا اللَّئِيمُ", "segs": [{"ar": "بَنَاتُ النَّاسِ أَمَانَةٌ يَا أُمَّهْ", "uz": "Odamlarning qizlari — bu omonat, onajon"}, {"ar": "لَا يُضَيِّعُهَا إِلَّا اللَّئِيمُ", "uz": "uni faqat past kishigina zoye qiladi"}], "full_uz": "Odamlarning qizlari — bu omonat, onajon, uni faqat past kishigina zoye qiladi.", "note": null},
  {"num": 209, "time": "00:26:41,319 --> 00:26:49,220", "arabic": "أَنْتَ تُجِيدُ الْمُبَرِّرَاتِ يَا وَلَدِي، ثُمَّ وَإِنْ كُنْتَ لَا تَمْلِكُ مَالًا فَقَدْ حُزْتَ ثَرْوَةً مِنَ الْعِلْمِ", "segs": [{"ar": "أَنْتَ تُجِيدُ الْمُبَرِّرَاتِ يَا وَلَدِي", "uz": "Bahonalar keltirishni yaxshi bilasan, o'g'lim"}, {"ar": "ثُمَّ وَإِنْ كُنْتَ لَا تَمْلِكُ مَالًا فَقَدْ حُزْتَ ثَرْوَةً مِنَ الْعِلْمِ", "uz": "Yana, mol-mulking bo'lmasa ham, ilmdan boylik topgansan"}], "full_uz": "Bahonalar keltirishni yaxshi bilasan, o'g'lim. Yana, mol-mulking bo'lmasa ham, ilmdan boylik topgansan.", "note": null},
  {"num": 213, "time": "00:26:49,220 --> 00:26:56,860", "arabic": "فَقُلْ لِي أَيُّهُمَا أَجَلُّ وَأَشْرَفُ، اَلْحَوْلُ أَمِ الْقُوَّةُ؟ حَسَنًا حَسَنًا يَا أُمَّهْ", "segs": [{"ar": "فَقُلْ لِي أَيُّهُمَا أَجَلُّ وَأَشْرَفُ، اَلْحَوْلُ أَمِ الْقُوَّةُ؟", "uz": "Ayt-chi, qaysi biri buyuk va sharaflirog'i — boylikmi yoki quvvatmi?"}, {"ar": "حَسَنًا حَسَنًا يَا أُمَّهْ", "uz": "Xo'p, xo'p, onajon"}], "full_uz": "Ayt-chi, qaysi biri buyuk va sharaflirog'i — hol (bойlik)mi yoki quvvat (ilm)mi? Xo'p, xo'p, onajon.", "note": null},
  {"num": 217, "time": "00:26:56,860 --> 00:27:04,480", "arabic": "مَا رَأْيُكِ أَنْ نُؤَجِّلَ الْحَدِيثَ إِلَى وَقْتٍ لَاحِقٍ، فَأَنَا مَشْغُولٌ قَلِيلًا وَلَا أُرِيدُ أَنْ أَتَأَخَّرَ عَلَى أَبِي الْمُغِيرَةِ", "segs": [{"ar": "مَا رَأْيُكِ أَنْ نُؤَجِّلَ الْحَدِيثَ إِلَى وَقْتٍ لَاحِقٍ", "uz": "Fikringiz qanday — suhbatni keyingi vaqtga qoldirsak?"}, {"ar": "فَأَنَا مَشْغُولٌ قَلِيلًا", "uz": "Biroz bandman"}, {"ar": "وَلَا أُرِيدُ أَنْ أَتَأَخَّرَ عَلَى أَبِي الْمُغِيرَةِ", "uz": "va Abu al-Mug'iraga kechikishni istamayman"}], "full_uz": "Fikringiz qanday — suhbatni keyingi vaqtga qoldirsak? Biroz bandman va Abu al-Mug'iraga kechikishni istamayman.", "note": null},
  {"num": 220, "time": "00:27:04,480 --> 00:27:08,920", "arabic": "اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Assalomu alaykum. Va alaykum assalom va rahmatulloh.", "note": null},
  {"num": 222, "time": "00:27:08,920 --> 00:27:29,540", "arabic": "مَنْ وَقَفَ فِي وَجْهِ الْمَلَاحِدَةِ الْكَافِرِينَ وَمَنْ تَصَدَّى لِلزَّنَادِقَةِ الْمَارِقِينَ، أَلَيْسُوا هُمُ الْمُعْتَزِلَةَ؟ أَلَمْ تَكُنْ لَهُمْ سَابِقَةُ الْفَضْلِ بِالدِّفَاعِ عَنِ الْإِسْلَامِ وَأَهْلِهِ؟", "segs": [{"ar": "مَنْ وَقَفَ فِي وَجْهِ الْمَلَاحِدَةِ الْكَافِرِينَ", "uz": "Kofir dahriylarga qarshi turgan kim edi"}, {"ar": "وَمَنْ تَصَدَّى لِلزَّنَادِقَةِ الْمَارِقِينَ", "uz": "va yo'ldan chiqqan zindiqlarga qarshi chiqqan kim edi"}, {"ar": "أَلَيْسُوا هُمُ الْمُعْتَزِلَةَ؟", "uz": "Mo'tazila emasmi?"}, {"ar": "أَلَمْ تَكُنْ لَهُمْ سَابِقَةُ الْفَضْلِ بِالدِّفَاعِ عَنِ الْإِسْلَامِ وَأَهْلِهِ؟", "uz": "Islom va uning ahlini himoya qilishda ularning oldingi xizmati yo'q edimi?"}], "full_uz": "Kofir dahriylarga qarshi turgan va yo'ldan chiqqan zindiqlarga qarshi chiqqan kimlar edi — Mo'tazila emasmi? Islom va uning ahlini himoya qilishda ularning oldingi xizmati yo'q edimi?", "note": null},
  {"num": 226, "time": "00:27:29,540 --> 00:27:37,740", "arabic": "أَلَمْ يَتَفَرَّقْ أَتْبَاعُ شَيْخِ وَاصِلِ بْنِ عَطَاءٍ رَحِمَهُ اللَّهُ فِي الْأَمْصَارِ الْإِسْلَامِيَّةِ رَادِّينَ عَلَى أَهْلِ الْأَهْوَاءِ وَالضَّلَالَاتِ؟", "segs": [{"ar": "أَلَمْ يَتَفَرَّقْ أَتْبَاعُ شَيْخِ وَاصِلِ بْنِ عَطَاءٍ رَحِمَهُ اللَّهُ", "uz": "Shayx Vosil ibn Ato'ning — Alloh unga rahmat qilsin — izdoshlari tarqalmadimi"}, {"ar": "فِي الْأَمْصَارِ الْإِسْلَامِيَّةِ", "uz": "islom shaharlariga"}, {"ar": "رَادِّينَ عَلَى أَهْلِ الْأَهْوَاءِ وَالضَّلَالَاتِ؟", "uz": "nafsparast va adashganlarga qarshi javob berib?"}], "full_uz": "Shayx Vosil ibn Ato'ning — Alloh unga rahmat qilsin — izdoshlari islom shaharlariga tarqalib, nafsparast va adashganlarga qarshi javob berishmadimi?", "note": "وَاصِلُ بْنُ عَطَاءٍ — Mo'tazila mazhabining asoschisi hisoblanadi."},
  {"num": 228, "time": "00:27:37,740 --> 00:27:50,500", "arabic": "مَا لَا تَعْلَمُونَهُ أَوْ تَغْفُلُونَ عَنْهُ أَنَّ أَهْلَ الْكُفْرِ لَا يَرْتَدِعُونَ إِلَّا بِإِحْدَى اثْنَتَيْنِ، بِسَيْفٍ صَارِمٍ أَوْ لِسَانٍ حَازِمٍ", "segs": [{"ar": "مَا لَا تَعْلَمُونَهُ أَوْ تَغْفُلُونَ عَنْهُ", "uz": "Bilmagan yoki g'aflatda qolgan narsangiz"}, {"ar": "أَنَّ أَهْلَ الْكُفْرِ لَا يَرْتَدِعُونَ إِلَّا بِإِحْدَى اثْنَتَيْنِ", "uz": "kufr ahli faqat ikki narsadan biri bilan to'xtaydi"}, {"ar": "بِسَيْفٍ صَارِمٍ أَوْ لِسَانٍ حَازِمٍ", "uz": "kesuvchi qilich yoki qat'iy til"}], "full_uz": "Bilmagan yoki g'aflatda qolgan narsangiz — kufr ahli faqat ikki narsadan biri bilan to'xtaydi: kesuvchi qilich yoki qat'iy til.", "note": null},
  {"num": 231, "time": "00:27:53,380 --> 00:28:07,860", "arabic": "نَحْنُ لَسْنَا أَصْحَابَ كَلَامٍ حَتَّى نُقَارِعَكَ الْحُجَّةَ بِالْحُجَّةِ يَا ابْنَ أَبِي دُؤَادٍ، وَلَكِنَّنَا قَوْمٌ نَتَعَرَّفُ دِينَنَا مِنَ الْكِتَابِ وَالسُّنَّةِ", "segs": [{"ar": "نَحْنُ لَسْنَا أَصْحَابَ كَلَامٍ", "uz": "Biz kalom ahli emasmiz"}, {"ar": "حَتَّى نُقَارِعَكَ الْحُجَّةَ بِالْحُجَّةِ يَا ابْنَ أَبِي دُؤَادٍ", "uz": "senga dalilga dalil bilan bahslashaylik, Ibn Abi Duvod"}, {"ar": "وَلَكِنَّنَا قَوْمٌ نَتَعَرَّفُ دِينَنَا مِنَ الْكِتَابِ وَالسُّنَّةِ", "uz": "biz esa dinimizni Kitob va Sunnadan tanigan qavmmiz"}], "full_uz": "Biz kalom ahli emasmiz, senga dalilga dalil bilan bahslashib turaylik, Ibn Abi Duvod. Biz esa dinimizni Kitob va Sunnadan tanigan qavmmiz.", "note": null},
  {"num": 233, "time": "00:28:07,860 --> 00:28:17,960", "arabic": "وَنَتَعَبَّدُ اللَّهَ بِمَا أَنْزَلَ لَا بِمَا نَرَى، أَمَّا أَنْتُمْ فَتُقَدِّمُونَ الرَّأْيَ عَلَى النَّصِّ وَالصَّوَابُ فِيمَا نَرَى", "segs": [{"ar": "وَنَتَعَبَّدُ اللَّهَ بِمَا أَنْزَلَ لَا بِمَا نَرَى", "uz": "Allohga U nozil qilgani bilan ibodat qilamiz, o'zimiz ko'rgan bilan emas"}, {"ar": "أَمَّا أَنْتُمْ فَتُقَدِّمُونَ الرَّأْيَ عَلَى النَّصِّ وَالصَّوَابُ فِيمَا نَرَى", "uz": "sizlar esa fikrni nassdan ustun qo'yasizlar, to'g'risi biz ko'rganimizcha shudir"}], "full_uz": "Allohga U nozil qilgani bilan ibodat qilamiz, o'zimiz ko'rgan bilan emas — sizlar esa fikrni nassdan ustun qo'yasizlar, to'g'risi biz ko'rganimizcha shudir.", "note": null},
  {"num": 235, "time": "00:28:17,960 --> 00:28:26,959", "arabic": "أَنْ نَقِفَ عِنْدَ حُدُودِ النَّصِّ نَفْهَمُهُ بِفَهْمِ النَّبِيِّ وَأَصْحَابِهِ، حَتَّى لَا تَزِلَّ أَقْدَامُنَا فِي مَزَالِقِ الْغَيِّ وَظُلُمَاتِ الضَّلَالِ", "segs": [{"ar": "أَنْ نَقِفَ عِنْدَ حُدُودِ النَّصِّ", "uz": "Nassning chegarasida to'xtashimiz"}, {"ar": "نَفْهَمُهُ بِفَهْمِ النَّبِيِّ وَأَصْحَابِهِ", "uz": "uni Payg'ambar va uning sahobalari tushungandek tushunishimiz"}, {"ar": "حَتَّى لَا تَزِلَّ أَقْدَامُنَا فِي مَزَالِقِ الْغَيِّ وَظُلُمَاتِ الضَّلَالِ", "uz": "toki oyoqlarimiz adashuv jarliklariga va zalolat zulmatlariga toymasin"}], "full_uz": "Nassning chegarasida to'xtab, uni Payg'ambar va uning sahobalari tushungandek tushunishimiz — toki oyoqlarimiz adashuv jarliklariga va zalolat zulmatlariga toymasin.", "note": null},
  {"num": 237, "time": "00:28:26,959 --> 00:28:40,099", "arabic": "تَأَخَّرَ زَوْجِي الْحَبِيبُ كَثِيرًا، فَأَيْنَ كَانَ؟ أَلَا يَعْلَمُ أَنَّهُ بَقِيَ مِنَ الْوَقْتِ الْقَلِيلُ", "segs": [{"ar": "تَأَخَّرَ زَوْجِي الْحَبِيبُ كَثِيرًا، فَأَيْنَ كَانَ؟", "uz": "Sevikli erim juda kechikdi, qayerda ekan?"}, {"ar": "أَلَا يَعْلَمُ أَنَّهُ بَقِيَ مِنَ الْوَقْتِ الْقَلِيلُ", "uz": "Vaqt ozgina qolganini bilmaydimi?"}], "full_uz": "Sevikli erim juda kechikdi — qayerda ekan? Vaqt ozgina qolganini bilmaydimi?", "note": null},
  {"num": 240, "time": "00:28:40,099 --> 00:28:45,479", "arabic": "وَتَصِلُ أُخْتِي شَهْنَازُ وَزَوْجُهَا وَهُوَ غَيْرُ مَوْجُودٍ؟ مَا طَلَبْتِهِ يَا زَوْجَةَ شَفِيعٍ", "segs": [{"ar": "وَتَصِلُ أُخْتِي شَهْنَازُ وَزَوْجُهَا وَهُوَ غَيْرُ مَوْجُودٍ؟", "uz": "Singlim Shahnoz va uning eri kelib qolsa-yu, u yo'q bo'lsa?"}, {"ar": "مَا طَلَبْتِهِ يَا زَوْجَةَ شَفِيعٍ", "uz": "Nima so'rasang ham, Shafi'ning xotini"}], "full_uz": "Singlim Shahnoz va uning eri kelib qolsa-yu, u yo'q bo'lsa? Nima so'rasang ham, Shafi'ning xotini.", "note": null},
  {"num": 242, "time": "00:28:45,479 --> 00:28:54,180", "arabic": "لَا يَكْفِيهِ يَوْمٌ كَامِلٌ حَتَّى أَجْلِبَهُ لَكِ، فَلَمْ أَتْرُكْ دُكَّانًا فِي سُوقٍ وَلَا حَانُوتًا فِي زَاوِيَةٍ إِلَّا وَدَخَلْتُهُ، ثُمَّ جِئْتُكِ عَلَى عَجَلٍ", "segs": [{"ar": "لَا يَكْفِيهِ يَوْمٌ كَامِلٌ حَتَّى أَجْلِبَهُ لَكِ", "uz": "Buni senga topib kelish uchun butun kunim ham yetmaydi"}, {"ar": "فَلَمْ أَتْرُكْ دُكَّانًا فِي سُوقٍ", "uz": "bozorda qoldirmagan do'kon yo'q"}, {"ar": "وَلَا حَانُوتًا فِي زَاوِيَةٍ إِلَّا وَدَخَلْتُهُ", "uz": "burchakda qoldirmagan rasta yo'q, hammasiga kirdim"}, {"ar": "ثُمَّ جِئْتُكِ عَلَى عَجَلٍ", "uz": "so'ng senga shoshib keldim"}], "full_uz": "Buni senga topib kelish uchun butun kunim ham yetmaydi — bozorda qoldirmagan do'kon, burchakda qoldirmagan rastam yo'q, hammasiga kirdim, so'ng senga shoshib keldim.", "note": null},
  {"num": 245, "time": "00:28:54,180 --> 00:29:02,220", "arabic": "فَلِمَ لَا تَتُوبُ يَا زَوْجِي؟ وَمَنْ لِي غَيْرَ زَوْجِي أُعَاتِبُهُ؟ ثُمَّ إِنَّكَ تَعْرِفُ أَنِّي لَا أَصْبِرُ عَلَى فِرَاقِكَ يَا شَفِيعُ", "segs": [{"ar": "فَلِمَ لَا تَتُوبُ يَا زَوْجِي؟", "uz": "Nega tavba qilmaysan, erim?"}, {"ar": "وَمَنْ لِي غَيْرَ زَوْجِي أُعَاتِبُهُ؟", "uz": "Erimdan boshqa kimni koyiy olardim?"}, {"ar": "ثُمَّ إِنَّكَ تَعْرِفُ", "uz": "Yana, sen bilasan"}, {"ar": "أَنِّي لَا أَصْبِرُ عَلَى فِرَاقِكَ يَا شَفِيعُ", "uz": "men sendan ajralishga chidayolmayman, Shafi'"}], "full_uz": "Nega tavba qilmaysan, erim? Erimdan boshqa kimni koyiy olardim? Yana, sen bilasan — men sendan ajralishga chidayolmayman, Shafi'.", "note": null},
  {"num": 248, "time": "00:29:02,220 --> 00:29:10,240", "arabic": "بِمَوْجِدَتِي أُخْتِي شَهْنَازَ قَطَعْتُ وَعْدًا أَنْ أُعَوِّضَهَا وَنَفْسِي عَنْ سِنِينِ الْفِرَاقِ وَالْعَذَابِ", "segs": [{"ar": "بِمَوْجِدَتِي أُخْتِي شَهْنَازَ", "uz": "Singlim Shahnozni topganimdan buyon"}, {"ar": "قَطَعْتُ وَعْدًا أَنْ أُعَوِّضَهَا وَنَفْسِي عَنْ سِنِينِ الْفِرَاقِ وَالْعَذَابِ", "uz": "ayriliq va azob yillarining o'rnini unga ham, o'zimga ham to'ldirishga va'da berganman"}], "full_uz": "Singlim Shahnozni topganimdan buyon, ayriliq va azob yillarining o'rnini unga ham, o'zimga ham to'ldirishga va'da berganman.", "note": null},
  {"num": 251, "time": "00:29:10,240 --> 00:29:14,420", "arabic": "يَا زَوْجَةَ شَفِيعٍ، هَا أَنْتِ تُضَيِّعِينَ الْوَقْتَ، وَإِذَا تَأَخَّرْتُ يَقَعُ اللَّوْمُ عَلَيَّ", "segs": [{"ar": "يَا زَوْجَةَ شَفِيعٍ، هَا أَنْتِ تُضَيِّعِينَ الْوَقْتَ", "uz": "Ey Shafi'ning xotini, mana sen vaqtni behuda o'tkazyapsan"}, {"ar": "وَإِذَا تَأَخَّرْتُ يَقَعُ اللَّوْمُ عَلَيَّ", "uz": "kechiksam, ayb menda bo'ladi"}], "full_uz": "Ey Shafi'ning xotini, mana sen vaqtni behuda o'tkazyapsan — kechiksam, ayb menda bo'ladi.", "note": null},
  {"num": 254, "time": "00:29:14,420 --> 00:29:21,220", "arabic": "صَدَقْتَ، يَكْفِينَا مَا ضَاعَ مِنَ الْوَقْتِ، سَأَبْدَأُ أَنَا بِتَحْضِيرِ الطَّعَامِ رَيْثَمَا تَسْتَبْدِلُ مَلَابِسَكَ لِاسْتِقْبَالِ الضُّيُوفِ", "segs": [{"ar": "صَدَقْتَ، يَكْفِينَا مَا ضَاعَ مِنَ الْوَقْتِ", "uz": "To'g'ri aytding, o'tgan vaqt yetadi bizga"}, {"ar": "سَأَبْدَأُ أَنَا بِتَحْضِيرِ الطَّعَامِ", "uz": "men taom tayyorlashni boshlayman"}, {"ar": "رَيْثَمَا تَسْتَبْدِلُ مَلَابِسَكَ لِاسْتِقْبَالِ الضُّيُوفِ", "uz": "sen mehmonlarni kutib olish uchun kiyimingni almashtirguningcha"}], "full_uz": "To'g'ri aytding, o'tgan vaqt yetadi bizga — sen mehmonlarni kutib olish uchun kiyimingni almashtirguningcha, men taom tayyorlashni boshlayman.", "note": null},
  {"num": 257, "time": "00:29:21,220 --> 00:29:39,559", "arabic": "تَفَضَّلِي يَا فَوْزُ، هَذَا صَكُّ عِتْقِكِ مِنَ الْعُبُودِيَّةِ", "segs": null, "full_uz": "Marhamat, Favz — bu sening qullikdan ozod bo'lganingga hujjat.", "note": "صَكُّ الْعِتْق — qullikdan ozod qilish hujjati."},
  {"num": 259, "time": "00:29:39,559 --> 00:29:48,799", "arabic": "فَمِثْلُكِ كَانَ حُرَّةً وَيَجِبُ أَنْ يَعِيشَ بَقِيَّةَ حَيَاتِهِ حُرَّةً", "segs": null, "full_uz": "Sen kabi qiz ozod bo'lgan va umrining qolganini ozod holda o'tkazishi kerak.", "note": null},
  {"num": 261, "time": "00:29:51,220 --> 00:30:05,039", "arabic": "بَعْدَ أَنْ عَرَفْنَا مَا حَلَّ بِكِ مِنْ ظُلْمٍ عَلَى يَدِ مَنْ لَا تَعْرِفُ الرَّحْمَةُ طَرِيقًا إِلَى قُلُوبِهِمْ، لَا يُمْكِنُ أَنْ نَقْبَلَ أَنْ تَبْقَيْ جَارِيَةً", "segs": [{"ar": "بَعْدَ أَنْ عَرَفْنَا مَا حَلَّ بِكِ مِنْ ظُلْمٍ", "uz": "Senga sodir bo'lgan zulmni bilganimizdan keyin"}, {"ar": "عَلَى يَدِ مَنْ لَا تَعْرِفُ الرَّحْمَةُ طَرِيقًا إِلَى قُلُوبِهِمْ", "uz": "rahm yuragiga yo'l topolmagan kishilarning qo'lida"}, {"ar": "لَا يُمْكِنُ أَنْ نَقْبَلَ", "uz": "rozi bo'la olmaymiz"}, {"ar": "أَنْ تَبْقَيْ جَارِيَةً", "uz": "seni cho'ri holida qolishingga"}], "full_uz": "Rahm yuragiga yo'l topolmagan kishilarning qo'lida senga sodir bo'lgan zulmni bilganimizdan keyin, seni cho'ri holida qolishingga rozi bo'la olmaymiz.", "note": null},
  {"num": 264, "time": "00:30:05,039 --> 00:30:12,920", "arabic": "أَيُّ كَلِمَاتٍ يُمْكِنُ أَنْ تُعَبِّرَ عَنْ شُكْرِي وَامْتِنَانِي لَكُمَا؟ أَنْتِ الْآنَ حُرَّةٌ كَمَا وَلَدَتْكِ أُمُّكِ", "segs": [{"ar": "أَيُّ كَلِمَاتٍ يُمْكِنُ أَنْ تُعَبِّرَ عَنْ شُكْرِي وَامْتِنَانِي لَكُمَا؟", "uz": "Sizlarga rahmat va minnatdorchiligimni qanday so'zlar bilan ifoda etsam?"}, {"ar": "أَنْتِ الْآنَ حُرَّةٌ كَمَا وَلَدَتْكِ أُمُّكِ", "uz": "Endi sen onang seni tug'gan kunidagidek ozodsan"}], "full_uz": "Sizlarga rahmat va minnatdorchiligimni qanday so'zlar bilan ifoda etsam? Endi sen onang seni tug'gan kunidagidek ozodsan.", "note": null},
  {"num": 266, "time": "00:30:12,920 --> 00:30:20,700", "arabic": "وَيُمْكِنُكِ أَنْ تُغَادِرِي هَذَا الْبَيْتَ فِي الْوَقْتِ الَّذِي تُرِيدِينَ، وَلَكِ أَنْ تَبْقَيْ فِيهِ بَقِيَّةَ عُمُرِكِ", "segs": [{"ar": "وَيُمْكِنُكِ أَنْ تُغَادِرِي هَذَا الْبَيْتَ فِي الْوَقْتِ الَّذِي تُرِيدِينَ", "uz": "Istagan vaqtingda bu uydan chiqib ketishing mumkin"}, {"ar": "وَلَكِ أَنْ تَبْقَيْ فِيهِ بَقِيَّةَ عُمُرِكِ", "uz": "umringning qolganini shu yerda o'tkazishing ham mumkin"}], "full_uz": "Istagan vaqtingda bu uydan chiqib ketishing mumkin, umringning qolganini shu yerda o'tkazishing ham mumkin.", "note": null},
  {"num": 268, "time": "00:30:20,700 --> 00:30:31,700", "arabic": "أَعْرِفُكِ فَتَاةً ذَكِيَّةً وَجَمِيلَةً، أَخِي يَطْلُبُكِ لِلزَّوَاجِ، فَمَا تَقُولِينَ؟", "segs": [{"ar": "أَعْرِفُكِ فَتَاةً ذَكِيَّةً وَجَمِيلَةً", "uz": "Seni aqlli va chiroyli qiz deb bilaman"}, {"ar": "أَخِي يَطْلُبُكِ لِلزَّوَاجِ، فَمَا تَقُولِينَ؟", "uz": "akam senga uylanishni so'rayapti, nima deysan?"}], "full_uz": "Seni aqlli va chiroyli qiz deb bilaman — akam senga uylanishni so'rayapti, nima deysan?", "note": null},
  {"num": 271, "time": "00:30:33,519 --> 00:30:43,240", "arabic": "أَتَقْبَلُ الْحُرَّةُ الْآنَ أَوْ...؟ مَعَ أَنَّكِ إِنْ قَبِلْتِ سَيَكُونُ يَوْمًا مِنْ أَجْمَلِ أَيَّامِ عُمُرِي، وَإِنْ لَمْ تَقْبَلِي...", "segs": [{"ar": "أَتَقْبَلُ الْحُرَّةُ الْآنَ أَوْ...؟", "uz": "Ozod bo'lgan qiz endi rozi bo'ladimi yoki...?"}, {"ar": "مَعَ أَنَّكِ إِنْ قَبِلْتِ سَيَكُونُ يَوْمًا مِنْ أَجْمَلِ أَيَّامِ عُمُرِي", "uz": "agar rozi bo'lsang, bu umrimning eng go'zal kunlaridan biri bo'ladi"}, {"ar": "وَإِنْ لَمْ تَقْبَلِي...", "uz": "agar rozi bo'lmasang esa..."}], "full_uz": "Ozod bo'lgan qiz endi rozi bo'ladimi yoki...? Agar rozi bo'lsang, bu umrimning eng go'zal kunlaridan biri bo'ladi, agar rozi bo'lmasang esa...", "note": null},
  {"num": 274, "time": "00:30:43,240 --> 00:30:52,340", "arabic": "وَافَقْتُ، وَلَكِنْ بِشَرْطٍ، إِنِّي أَسْمَعُكِ، أَنْ تُسَاعِدَنِي فِي الْبَحْثِ عَنْ أَهْلِي وَأُخْتِي، وَأَنَا مُوَافِقٌ", "segs": [{"ar": "وَافَقْتُ، وَلَكِنْ بِشَرْطٍ", "uz": "Roziman, lekin bir shart bilan"}, {"ar": "أَنْ تُسَاعِدَنِي فِي الْبَحْثِ عَنْ أَهْلِي وَأُخْتِي، وَأَنَا مُوَافِقٌ", "uz": "Oilam va singlimni izlashda menga yordam berishing kerak. Men roziman"}], "full_uz": "Roziman, lekin bir shart bilan. Eshityapman. Oilam va singlimni izlashda menga yordam berishing kerak. Men roziman.", "note": null},
  {"num": 279, "time": "00:30:52,340 --> 00:31:09,200", "arabic": "شَهْنَازُ، لَقَدْ وَجَدْتُ أُخْتَكِ فَوْزَ", "segs": null, "full_uz": "Shahnoz! Singling Favzni topdim.", "note": null},
  {"num": 284, "time": "00:31:09,200 --> 00:31:18,420", "arabic": "وَجَدْتُهَا", "segs": null, "full_uz": "Uni topdim.", "note": null},
  {"num": 285, "time": "00:31:20,380 --> 00:31:26,420", "arabic": "أَحَقًّا مَا تَقُولُ؟ وَجَدْتُهَا، نَعَمْ نَعَمْ، إِنَّهَا هُنَا تَعِيشُ فِي بَغْدَادَ", "segs": [{"ar": "أَحَقًّا مَا تَقُولُ؟", "uz": "Rostdan aytyapsanmi?"}, {"ar": "وَجَدْتُهَا، نَعَمْ نَعَمْ", "uz": "Topdim. Ha, ha"}, {"ar": "إِنَّهَا هُنَا تَعِيشُ فِي بَغْدَادَ", "uz": "u shu yerda, Bag'dodda yashaydi"}], "full_uz": "Rostdan aytyapsanmi? Topdim. Ha, ha — u shu yerda, Bag'dodda yashaydi.", "note": null},
  {"num": 289, "time": "00:31:26,420 --> 00:31:35,160", "arabic": "مَرْوَانُ، أَيْنَ هِيَ؟ لِمَ لَمْ تَأْتِ مَعَكَ؟ أَيْنَ كَانَتْ مُخْتَفِيَةً كُلَّ هَذِهِ السِّنِينَ؟", "segs": [{"ar": "مَرْوَانُ، أَيْنَ هِيَ؟", "uz": "Marvon, u qayerda?"}, {"ar": "لِمَ لَمْ تَأْتِ مَعَكَ؟", "uz": "Nega sen bilan kelmadi?"}, {"ar": "أَيْنَ كَانَتْ مُخْتَفِيَةً كُلَّ هَذِهِ السِّنِينَ؟", "uz": "Shuncha yillar qayerda yashiringan edi?"}], "full_uz": "Marvon, u qayerda? Nega sen bilan kelmadi? Shuncha yillar qayerda yashiringan edi?", "note": null},
  {"num": 292, "time": "00:31:35,160 --> 00:31:39,520", "arabic": "أَرْجُوكَ أَخْبِرْنِي يَا مَرْوَانُ أَيْنَ هِيَ، أُرِيدُ أَنْ أَرَاهَا", "segs": [{"ar": "أَرْجُوكَ أَخْبِرْنِي يَا مَرْوَانُ أَيْنَ هِيَ", "uz": "Iltimos, ayt menga, Marvon, u qayerda"}, {"ar": "أُرِيدُ أَنْ أَرَاهَا", "uz": "uni ko'rmoqchiman"}], "full_uz": "Iltimos, ayt menga, Marvon, u qayerda — uni ko'rmoqchiman.", "note": null},
  {"num": 294, "time": "00:31:39,520 --> 00:31:41,520", "arabic": "اِهْدَئِي اِهْدَئِي، إِنَّهَا تَعِيشُ فِي بَيْتِ زَوْجِهَا", "segs": null, "full_uz": "Xotirjam bo'l, xotirjam bo'l — u eri uyida yashaydi.", "note": null},
  {"num": 296, "time": "00:31:41,519 --> 00:31:55,420", "arabic": "هَلْ تَزَوَّجَتْ أَيْضًا؟ نَعَمْ، لَقَدْ تَزَوَّجَتْ مِنْ أَحَدِ حُرَّاسِ الْخَلِيفَةِ", "segs": [{"ar": "هَلْ تَزَوَّجَتْ أَيْضًا؟", "uz": "U ham turmushga chiqdimi?"}, {"ar": "نَعَمْ، لَقَدْ تَزَوَّجَتْ مِنْ أَحَدِ حُرَّاسِ الْخَلِيفَةِ", "uz": "Ha, xalifaning soqchilaridan biriga turmushga chiqdi"}], "full_uz": "U ham turmushga chiqdimi? Ha, xalifaning soqchilaridan biriga turmushga chiqdi.", "note": null},
  {"num": 298, "time": "00:31:55,420 --> 00:32:04,139", "arabic": "لَا أُصَدِّقُ مَا تَقُولُ يَا مَرْوَانُ، أُرِيدُ أَنْ أَرَاهَا، أَرْجُوكَ خُذْنِي إِلَيْهَا", "segs": [{"ar": "لَا أُصَدِّقُ مَا تَقُولُ يَا مَرْوَانُ", "uz": "Aytganingga ishonmayapman, Marvon"}, {"ar": "أُرِيدُ أَنْ أَرَاهَا", "uz": "uni ko'rmoqchiman"}, {"ar": "أَرْجُوكَ خُذْنِي إِلَيْهَا", "uz": "iltimos meni uning oldiga olib bor"}], "full_uz": "Aytganingga ishonmayapman, Marvon — uni ko'rmoqchiman, iltimos meni uning oldiga olib bor.", "note": null},
  {"num": 300, "time": "00:32:04,139 --> 00:32:05,700", "arabic": "سَآخُذُكِ", "segs": null, "full_uz": "Olib boraman.", "note": null},
  {"num": 301, "time": "00:32:11,519 --> 00:32:18,539", "arabic": "هَيَّا يَا شَاهْنَازُ، لَا نُرِيدُ أَنْ نَتَأَخَّرَ عَلَى أُخْتِكِ فَوْزَ وَزَوْجِهَا شَفِيعٍ", "segs": [{"ar": "هَيَّا يَا شَاهْنَازُ", "uz": "Yur, Shahnoz"}, {"ar": "لَا نُرِيدُ أَنْ نَتَأَخَّرَ عَلَى أُخْتِكِ فَوْزَ وَزَوْجِهَا شَفِيعٍ", "uz": "singling Favz va uning eri Shafi'ga kechikmaylik"}], "full_uz": "Yur, Shahnoz — singling Favz va uning eri Shafi'ga kechikmaylik.", "note": null},
  {"num": 303, "time": "00:32:18,539 --> 00:32:25,339", "arabic": "هَا قَدِ انْتَهَيْتُ، هَيَّا بِنَا، حِينَ نَذْهَبُ إِلَى أُخْتِكِ فَوْزَ", "segs": [{"ar": "هَا قَدِ انْتَهَيْتُ، هَيَّا بِنَا", "uz": "Mana, tugatdim, ketdik"}, {"ar": "حِينَ نَذْهَبُ إِلَى أُخْتِكِ فَوْزَ", "uz": "Singlingnikiga borganimizda"}], "full_uz": "Mana, tugatdim, ketdik. Singlingnikiga borganimizda.", "note": null},
  {"num": 306, "time": "00:32:25,339 --> 00:32:34,940", "arabic": "أَرَى فِي عَيْنَيْكِ سَعَادَةً لَا أَرَاهَا فِي أَوْقَاتٍ أُخْرَى، حَتَّى أَنَّنِي كُنْتُ أَغَارُ مِنْهَا، وَكَيْفَ لَا أَكُونُ سَعِيدَةً وَهِيَ كُلُّ مَا تَبَقَّى لِي مِنْ أَهْلِي؟", "segs": [{"ar": "أَرَى فِي عَيْنَيْكِ سَعَادَةً لَا أَرَاهَا فِي أَوْقَاتٍ أُخْرَى", "uz": "Ko'zlaringda boshqa vaqtlarda ko'rmagan baxtni ko'ryapman"}, {"ar": "حَتَّى أَنَّنِي كُنْتُ أَغَارُ مِنْهَا", "uz": "hatto unga hasad qilardim"}, {"ar": "وَكَيْفَ لَا أَكُونُ سَعِيدَةً", "uz": "Qanday baxtli bo'lmay"}, {"ar": "وَهِيَ كُلُّ مَا تَبَقَّى لِي مِنْ أَهْلِي؟", "uz": "u oilamdan menga qolgan yagona kishi bo'lsa?"}], "full_uz": "Ko'zlaringda boshqa vaqtlarda ko'rmagan baxtni ko'ryapman — hatto unga hasad qilardim. Qanday baxtli bo'lmay, u oilamdan menga qolgan yagona kishi bo'lsa?", "note": null},
  {"num": 309, "time": "00:32:34,940 --> 00:32:39,759", "arabic": "بَعْدَ وَفَاةِ أُمِّي وَأَبِي لَمْ يَبْقَ لِي فِي هَذِهِ الدُّنْيَا إِلَّا فَوْزُ", "segs": [{"ar": "بَعْدَ وَفَاةِ أُمِّي وَأَبِي", "uz": "Onam va otam vafotidan keyin"}, {"ar": "لَمْ يَبْقَ لِي فِي هَذِهِ الدُّنْيَا إِلَّا فَوْزُ", "uz": "bu dunyoda faqat Favz qoldi menga"}], "full_uz": "Onam va otam vafotidan keyin bu dunyoda faqat Favz qoldi menga.", "note": null},
  {"num": 311, "time": "00:32:39,759 --> 00:32:45,140", "arabic": "وَأَنَا يَا شَاهْنَازُ؟ أَلَيْسَ لِي مَكَانٌ فِي قَلْبِكِ؟", "segs": null, "full_uz": "Ya men-chi, Shahnoz? Qalbingda menga o'rin yo'qmi?", "note": null},
  {"num": 313, "time": "00:32:45,140 --> 00:32:49,839", "arabic": "زَوْجِي فِي سُوَيْدَاءِ قَلْبِي وَلَكَ كُلُّ عُمُرِي وَحَيَاتِي", "segs": null, "full_uz": "Erim qalbimning tubida, umrim va hayotim esa senga tegishli.", "note": "سُوَيْدَاءُ الْقَلْب — qalbning eng chuqur, eng nozik joyi."},
  {"num": 315, "time": "00:32:49,839 --> 00:32:55,200", "arabic": "هَيَّا يَا أَبَا فَوْزَ، هَيَّا، لَا أُرِيدُ أَنْ أَتَأَخَّرَ أَكْثَرَ مِنْ ذَلِكَ، هَيَّا", "segs": [{"ar": "هَيَّا يَا أَبَا فَوْزَ، هَيَّا", "uz": "Yur, Abu Favz, yur"}, {"ar": "لَا أُرِيدُ أَنْ أَتَأَخَّرَ أَكْثَرَ مِنْ ذَلِكَ، هَيَّا", "uz": "bundan ortiq kechikishni istamayman, yur"}], "full_uz": "Yur, Abu Favz, yur — bundan ortiq kechikishni istamayman, yur.", "note": null},
  {"num": 320, "time": "00:33:01,720 --> 00:33:12,160", "arabic": "أَبَا عَبْدِ اللَّهِ، اَلسَّلَامُ عَلَيْكُمْ، وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": [{"ar": "أَبَا عَبْدِ اللَّهِ، اَلسَّلَامُ عَلَيْكُمْ", "uz": "Abu Abdulloh, assalomu alaykum"}, {"ar": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "uz": "Va alaykum assalom va rahmatulloh"}], "full_uz": "Abu Abdulloh, assalomu alaykum. Va alaykum assalom va rahmatulloh.", "note": null},
  {"num": 322, "time": "00:33:12,160 --> 00:33:17,019", "arabic": "لَدَيَّ سُؤَالٌ أَعْرِفُ أَنَّ جَوَابَهُ عِنْدَكَ، قُلْ مَا عِنْدَكَ يَا أَخِي خَيْرًا", "segs": [{"ar": "لَدَيَّ سُؤَالٌ أَعْرِفُ أَنَّ جَوَابَهُ عِنْدَكَ", "uz": "Javobi sizda ekanini bilgan bir savolim bor"}, {"ar": "قُلْ مَا عِنْدَكَ يَا أَخِي خَيْرًا", "uz": "Ayting, birodarim, xayrli bo'lsin"}], "full_uz": "Javobi sizda ekanini bilgan bir savolim bor. Ayting, birodarim, xayrli bo'lsin.", "note": null},
  {"num": 324, "time": "00:33:17,019 --> 00:33:26,160", "arabic": "لَحِقْتُ بِصَلَاةِ جَمَاعَةٍ وَكَانَ الْإِمَامُ رَاكِعًا فَكَبَّرْتُ رَاكِعًا، فَهَلْ تُعَدُّ لِيَ التَّكْبِيرَةُ الَّتِي رَكَعْتُ بِهَا عَنْ تَكْبِيرَةِ الِافْتِتَاحِ؟", "segs": [{"ar": "لَحِقْتُ بِصَلَاةِ جَمَاعَةٍ وَكَانَ الْإِمَامُ رَاكِعًا", "uz": "Jamoat namoziga yetib bordim, imom ruku'da edi"}, {"ar": "فَكَبَّرْتُ رَاكِعًا", "uz": "men ham ruku'ga tushib takbir aytdim"}, {"ar": "فَهَلْ تُعَدُّ لِيَ التَّكْبِيرَةُ الَّتِي رَكَعْتُ بِهَا عَنْ تَكْبِيرَةِ الِافْتِتَاحِ؟", "uz": "shu takbir menga iftitoh takbiri o'rniga hisoblanadimi?"}], "full_uz": "Jamoat namoziga yetib bordim, imom ruku'da edi, men ruku'ga tushib takbir aytdim — shu takbir menga iftitoh takbiri o'rniga hisoblanadimi?", "note": "تَكْبِيرَةُ الِافْتِتَاح — namozni boshlash uchun aytiladigan birinchi «Allohu akbar»."},
  {"num": 327, "time": "00:33:26,160 --> 00:33:35,140", "arabic": "إِنْ نَوَيْتَ بِتِلْكَ التَّكْبِيرَةِ تَكْبِيرَةَ الِافْتِتَاحِ أَجَلْ، فَقَدْ قَرَأْتُ عَلَى أَبِي عَبْدِ اللَّهِ عَبْدِ الْأَعْلَى عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ عَنْ سَالِمٍ", "segs": [{"ar": "إِنْ نَوَيْتَ بِتِلْكَ التَّكْبِيرَةِ تَكْبِيرَةَ الِافْتِتَاحِ أَجَلْ", "uz": "Agar shu takbir bilan iftitoh takbirini niyat qilgan bo'lsang, ha, bo'ladi"}, {"ar": "فَقَدْ قَرَأْتُ عَلَى أَبِي عَبْدِ اللَّهِ عَبْدِ الْأَعْلَى", "uz": "men Abu Abdulloh Abd al-A'loga o'qib eshitganman"}, {"ar": "عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ عَنْ سَالِمٍ", "uz": "u Ma'mardan, u az-Zuhriydan, u Solimdan"}], "full_uz": "Agar shu takbir bilan iftitoh takbirini niyat qilgan bo'lsang, ha, bo'ladi — men Abu Abdulloh Abd al-A'loga, u Mа'mardan, u az-Zuhriydan, u Solimdan o'qib eshitganman.", "note": null},
  {"num": 330, "time": "00:33:35,140 --> 00:33:45,380", "arabic": "عَنِ ابْنِ عُمَرَ وَزَيْدِ بْنِ ثَابِتٍ قَالَ: إِذَا أَدْرَكَ الرَّجُلُ الْقَوْمَ رُكُوعًا فَإِنَّهُ يُجْزِئُهُ تَكْبِيرَةٌ وَاحِدَةٌ", "segs": [{"ar": "عَنِ ابْنِ عُمَرَ وَزَيْدِ بْنِ ثَابِتٍ قَالَ", "uz": "Ibn Umar va Zayd ibn Sobitdan rivoyat qilinadi, dedi"}, {"ar": "إِذَا أَدْرَكَ الرَّجُلُ الْقَوْمَ رُكُوعًا فَإِنَّهُ يُجْزِئُهُ تَكْبِيرَةٌ وَاحِدَةٌ", "uz": "agar kishi jamoatga ruku' holida yetsa, unga bitta takbir kifoya qiladi"}], "full_uz": "Ibn Umar va Zayd ibn Sobitdan rivoyat qilinadi, dedi: agar kishi jamoatga ruku' holida yetsa, unga bitta takbir kifoya qiladi.", "note": null},
  {"num": 333, "time": "00:33:45,380 --> 00:33:50,180", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا أَبَا عَبْدِ اللَّهِ، أَسْتَوْدِعُكَ اللَّهَ يَا أَبَا الْوَلِيدِ، اَلسَّلَامُ عَلَيْكُمْ", "segs": [{"ar": "جَزَاكَ اللَّهُ خَيْرًا يَا أَبَا عَبْدِ اللَّهِ", "uz": "Alloh senga yaxshilik bersin, Abu Abdulloh"}, {"ar": "أَسْتَوْدِعُكَ اللَّهَ يَا أَبَا الْوَلِيدِ", "uz": "Seni Allohga topshiraman, Abu al-Valid"}, {"ar": "اَلسَّلَامُ عَلَيْكُمْ", "uz": "Assalomu alaykum"}], "full_uz": "Alloh senga yaxshilik bersin, Abu Abdulloh. Seni Allohga topshiraman, Abu al-Valid. Assalomu alaykum.", "note": null},
  {"num": 336, "time": "00:33:50,180 --> 00:33:57,940", "arabic": "إِذَا تَحَامَلَ مَا بَعْدَهُ تَحَامُلٌ يَا أَبَا الْمُغِيرَةِ، هَلْ هَذَا هُوَ الْحَقُّ الَّذِي يُقَرِّعُ الْمُعْتَزِلَةَ وَأَشْيَاعَهُمْ؟", "segs": [{"ar": "إِذَا تَحَامَلَ مَا بَعْدَهُ تَحَامُلٌ يَا أَبَا الْمُغِيرَةِ", "uz": "Agar zulm bo'lsa, undan keyingisi ham zulmdir, Abu al-Mug'ira"}, {"ar": "هَلْ هَذَا هُوَ الْحَقُّ الَّذِي يُقَرِّعُ الْمُعْتَزِلَةَ وَأَشْيَاعَهُمْ؟", "uz": "Mo'tazila va uning izdoshlarini qoralaydigan haqiqat shumi?"}], "full_uz": "Agar zulm bo'lsa, undan keyingisi ham zulmdir, Abu al-Mug'ira — Mo'tazila va uning izdoshlarini qoralaydigan haqiqat shumi?", "note": null},
  {"num": 338, "time": "00:33:57,940 --> 00:34:04,059", "arabic": "فَهُمْ حِينَ يُضْرِبُونَ عَنْ نُصُوصِ كِتَابِ اللَّهِ وَسُنَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفْحًا", "segs": [{"ar": "فَهُمْ حِينَ يُضْرِبُونَ عَنْ نُصُوصِ كِتَابِ اللَّهِ", "uz": "Ular Alloh kitobining nasslaridan yuz o'girib qo'yganlarida"}, {"ar": "وَسُنَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفْحًا", "uz": "va Rasuli sollallohu alayhi va sallam sunnatidan ham"}], "full_uz": "Ular Alloh kitobi va Rasuli sollallohu alayhi va sallam sunnatining nasslaridan yuz o'girib qo'yganlarida.", "note": "أَضْرَبَ عَنِ الشَّيْءِ صَفْحًا — biror narsadan butunlay yuz o'girib, e'tiborsiz qoldirmoq."},
  {"num": 341, "time": "00:34:04,580 --> 00:34:18,240", "arabic": "أُمُورُ مَكَّةَ", "segs": null, "full_uz": "Makka ishlari.", "note": null},
  {"num": 343, "time": "00:34:18,240 --> 00:34:28,120", "arabic": "لَمْ أَتَمَالَكْ نَفْسِي يَا أَبَا عَبْدِ اللَّهِ مِنَ الرَّدِّ عَلَى ابْنِ أَبِي دُؤَادٍ وَأَنَا أَسْمَعُهُ يَقُولُ مَا يَقُولُ", "segs": [{"ar": "لَمْ أَتَمَالَكْ نَفْسِي يَا أَبَا عَبْدِ اللَّهِ", "uz": "O'zimni tuta olmadim, Abu Abdulloh"}, {"ar": "مِنَ الرَّدِّ عَلَى ابْنِ أَبِي دُؤَادٍ", "uz": "Ibn Abi Duvodga javob berishdan"}, {"ar": "وَأَنَا أَسْمَعُهُ يَقُولُ مَا يَقُولُ", "uz": "u aytganini eshitib turib"}], "full_uz": "O'zimni tuta olmadim, Abu Abdulloh, Ibn Abi Duvodga javob berishdan — u aytganini eshitib turib.", "note": null},
  {"num": 345, "time": "00:34:28,120 --> 00:34:34,840", "arabic": "هَوِّنْ عَلَيْكَ يَا أَبَا الْمُغِيرَةِ، كُلُّ مَا أُرِيدُهُ مِنْكَ أَلَّا تُجَالِسَ أَمْثَالَ هَذَا الرَّجُلِ", "segs": [{"ar": "هَوِّنْ عَلَيْكَ يَا أَبَا الْمُغِيرَةِ", "uz": "O'zingga yengil ol, Abu al-Mug'ira"}, {"ar": "كُلُّ مَا أُرِيدُهُ مِنْكَ أَلَّا تُجَالِسَ أَمْثَالَ هَذَا الرَّجُلِ", "uz": "sendan istagan yagona narsam, bunday kishilar bilan o'tirmasliging"}], "full_uz": "O'zingga yengil ol, Abu al-Mug'ira — sendan istagan yagona narsam, bunday kishilar bilan o'tirmasliging.", "note": null},
  {"num": 348, "time": "00:34:34,840 --> 00:34:40,120", "arabic": "فَإِنَّ مُجَالَسَتَهُمْ تُرْدِي، وَإِيَّاكَ أَنْ تُكَلَّفَ بِالرَّدِّ عَلَيْهِمْ", "segs": [{"ar": "فَإِنَّ مُجَالَسَتَهُمْ تُرْدِي", "uz": "Ular bilan o'tirish halok qiladi"}, {"ar": "وَإِيَّاكَ أَنْ تُكَلَّفَ بِالرَّدِّ عَلَيْهِمْ", "uz": "ularga javob berishga urinmaslikni ham unutma"}], "full_uz": "Ular bilan o'tirish halok qiladi — ularga javob berishga urinmaslikni ham unutma.", "note": null},
  {"num": 350, "time": "00:34:40,120 --> 00:34:49,559", "arabic": "فَإِنَّ الرَّدَّ عَلَيْهِمْ بِالْمَرْءِ يُسْدِي، اِسْتَغْفِرِ اللَّهَ الْعَلِيَّ الْعَظِيمَ، اَللَّهُمَّ عَافِنَا مِنَ الضَّلَالِ وَأَهْلِهِ، اَللَّهُمَّ آمِينَ", "segs": [{"ar": "فَإِنَّ الرَّدَّ عَلَيْهِمْ بِالْمَرْءِ يُسْدِي", "uz": "Ularga javob berish kishiga zarar keltiradi"}, {"ar": "اِسْتَغْفِرِ اللَّهَ الْعَلِيَّ الْعَظِيمَ", "uz": "Alloh Aliyy va Azimdan mag'firat so'rayman"}, {"ar": "اَللَّهُمَّ عَافِنَا مِنَ الضَّلَالِ وَأَهْلِهِ، اَللَّهُمَّ آمِينَ", "uz": "Allohim, bizni zalolat va uning ahlidan asra. Omin, Allohim"}], "full_uz": "Ularga javob berish kishiga zarar keltiradi. Alloh Aliyy va Azimdan mag'firat so'rayman. Allohim, bizni zalolat va uning ahlidan asra. Omin, Allohim.", "note": null},
  {"num": 354, "time": "00:34:56,340 --> 00:35:06,039", "arabic": "اَلْحَقُّ يَا أَبَا عَبْدِ اللَّهِ أَنَّكَ أَحْسَنْتَ فِي كِتَابِكَ الرِّسَالَةِ", "segs": [{"ar": "اَلْحَقُّ يَا أَبَا عَبْدِ اللَّهِ", "uz": "Haqiqatan ham, Abu Abdulloh"}, {"ar": "أَنَّكَ أَحْسَنْتَ فِي كِتَابِكَ الرِّسَالَةِ", "uz": "«ar-Risala» kitobingizda a'lo ish qilgansiz"}], "full_uz": "Haqiqatan ham, Abu Abdulloh, «ar-Risala» kitobingizda a'lo ish qilgansiz.", "note": null},
  {"num": 355, "time": "00:35:06,039 --> 00:35:13,079", "arabic": "لَقَدْ وَضَعْتَ لِأَهْلِ الْعِلْمِ أُصُولًا فِي مَعْرِفَةِ دَلَائِلِ الشَّرِيعَةِ", "segs": null, "full_uz": "Ilm ahliga shariat dalillarini bilishda asoslar qo'ydingiz.", "note": null},
  {"num": 356, "time": "00:35:13,079 --> 00:35:20,460", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي وَفَّقَنِي إِلَى هَذَا وَمَنَّ عَلَيَّ بِشُيُوخٍ أَجِلَّاءَ", "segs": [{"ar": "اَلْحَمْدُ لِلَّهِ الَّذِي وَفَّقَنِي إِلَى هَذَا", "uz": "Meni bunga muvaffaq qilgan Allohga hamd bo'lsin"}, {"ar": "وَمَنَّ عَلَيَّ بِشُيُوخٍ أَجِلَّاءَ", "uz": "va ulug' shayxlar bilan ne'mat qilgan"}], "full_uz": "Meni bunga muvaffaq qilgan va ulug' shayxlar bilan ne'mat qilgan Allohga hamd bo'lsin.", "note": null},
  {"num": 358, "time": "00:35:20,460 --> 00:35:27,839", "arabic": "كَمَالِكِ بْنِ أَنَسٍ رَحِمَهُ اللَّهُ، وَكَأَمْثَالِكَ يَا شَيْخَنَا أَطَالَ اللَّهُ فِي عُمُرِكَ", "segs": [{"ar": "كَمَالِكِ بْنِ أَنَسٍ رَحِمَهُ اللَّهُ", "uz": "Molik ibn Anas kabi — Alloh unga rahmat qilsin"}, {"ar": "وَكَأَمْثَالِكَ يَا شَيْخَنَا أَطَالَ اللَّهُ فِي عُمُرِكَ", "uz": "va siz kabilar, ey shayximiz, Alloh umringizni uzoq qilsin"}], "full_uz": "Molik ibn Anas kabi — Alloh unga rahmat qilsin — va siz kabilar, ey shayximiz, Alloh umringizni uzoq qilsin.", "note": null},
  {"num": 360, "time": "00:35:27,839 --> 00:35:35,879", "arabic": "بَارَكَ اللَّهُ فِيكَ أَيُّهَا الشَّافِعِيُّ، لَقَدِ اسْتَنْبَطْتَ الْقَوَاعِدَ الَّتِي يَرْجِعُ إِلَيْهَا أَهْلُ الْعِلْمِ", "segs": [{"ar": "بَارَكَ اللَّهُ فِيكَ أَيُّهَا الشَّافِعِيُّ", "uz": "Alloh senga barakot bersin, ey Shofi'iy"}, {"ar": "لَقَدِ اسْتَنْبَطْتَ الْقَوَاعِدَ الَّتِي يَرْجِعُ إِلَيْهَا أَهْلُ الْعِلْمِ", "uz": "ilm ahli murojaat qiladigan qoidalarni siz chiqarib berdingiz"}], "full_uz": "Alloh senga barakot bersin, ey Shofi'iy — ilm ahli murojaat qiladigan qoidalarni siz chiqarib berdingiz.", "note": null},
  {"num": 362, "time": "00:35:35,879 --> 00:35:44,500", "arabic": "فِي مَعْرِفَةِ مَرَاتِبِ أَدِلَّةِ الشَّرْعِ وَبَيَانِ مَنْزِلَةِ السُّنَّةِ وَحُجِّيَّةِ الْإِجْمَاعِ وَالْقِيَاسِ", "segs": [{"ar": "فِي مَعْرِفَةِ مَرَاتِبِ أَدِلَّةِ الشَّرْعِ وَبَيَانِ مَنْزِلَةِ السُّنَّةِ", "uz": "Shariat dalillarining darajalarini bilishda va sunnatning o'rnini bayon qilishda"}, {"ar": "وَحُجِّيَّةِ الْإِجْمَاعِ وَالْقِيَاسِ", "uz": "hamda ijmo va qiyosning hujjatligida"}], "full_uz": "Shariat dalillarining darajalarini bilishda, sunnatning o'rnini va ijmo hamda qiyosning hujjatligini bayon qilishda.", "note": null},
  {"num": 364, "time": "00:35:44,500 --> 00:35:53,940", "arabic": "لَقَدْ أَحْسَنْتَ إِلَى أَهْلِ الْعِلْمِ وَأَفَدْتَهُمْ، فَجَزَاكَ اللَّهُ عَنِ الْإِسْلَامِ خَيْرًا", "segs": [{"ar": "لَقَدْ أَحْسَنْتَ إِلَى أَهْلِ الْعِلْمِ وَأَفَدْتَهُمْ", "uz": "Ilm ahliga yaxshilik qilib, ularga foyda yetkazding"}, {"ar": "فَجَزَاكَ اللَّهُ عَنِ الْإِسْلَامِ خَيْرًا", "uz": "Alloh senga Islom nomidan yaxshilik bersin"}], "full_uz": "Ilm ahliga yaxshilik qilib, ularga foyda yetkazding — Alloh senga Islom nomidan yaxshilik bersin.", "note": null},
  {"num": 366, "time": "00:35:53,940 --> 00:36:04,600", "arabic": "شَافَاكَ اللَّهُ وَعَافَاكَ يَا شَيْخَنَا، مَا كَانَ يَجِبُ عَلَيْكَ أَنْ تُتْعِبَ نَفْسَكَ بِالْقُدُومِ إِلَيْنَا", "segs": [{"ar": "شَافَاكَ اللَّهُ وَعَافَاكَ يَا شَيْخَنَا", "uz": "Alloh sizga shifo va salomatlik bersin, shayximiz"}, {"ar": "مَا كَانَ يَجِبُ عَلَيْكَ أَنْ تُتْعِبَ نَفْسَكَ بِالْقُدُومِ إِلَيْنَا", "uz": "bizga kelib, o'zingizni bezovta qilishingiz kerak emas edi"}], "full_uz": "Alloh sizga shifo va salomatlik bersin, shayximiz — bizga kelib, o'zingizni bezovta qilishingiz kerak emas edi.", "note": null},
  {"num": 368, "time": "00:36:04,600 --> 00:36:10,820", "arabic": "وَاجِبُنَا نَحْنُ أَنْ نَزُورَكَ وَنَقُومَ عَلَى خِدْمَتِكَ", "segs": null, "full_uz": "Bizning burchimiz — sizni ziyorat qilib, xizmatingizda bo'lish.", "note": null},
  {"num": 369, "time": "00:36:10,820 --> 00:36:15,820", "arabic": "شَوْقِي لِلْحَدِيثِ مَعَكَ أَمَدَّنِي بِالْقُوَّةِ", "segs": null, "full_uz": "Siz bilan suhbatga bo'lgan ishtiyoqim menga kuch bag'ishladi.", "note": null},
  {"num": 370, "time": "00:36:15,820 --> 00:36:20,500", "arabic": "إِنَّ الْحَدِيثَ مَعَكَ يُنْسِينِي مَرَضِي", "segs": null, "full_uz": "Siz bilan suhbat menga kasalligimni unutdiradi.", "note": null},
  {"num": 371, "time": "00:36:20,500 --> 00:36:24,320", "arabic": "سَأُحْضِرُ لَكَ شَرَابًا يُرِيحُكَ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, sizga yengillik beradigan bir sharbat olib kelaman.", "note": null},
];

